    const memoryAfter = benchmark.getMemoryUsage();
    console.log(boldCyan('Memory Usage:'));
    console.log(`  Before: ${benchmark.formatMemory(memoryBefore.heapUsed)} / ${benchmark.formatMemory(memoryBefore.heapTotal)}`);
