import { ActionEngine } from '../action-engine';
import { DatabaseManager, UserReputation } from '../database-manager';
import { Severity, Action, SecurityConfig } from '../../types';
import * as fs from 'fs';
import * as path from 'path';

describe('ActionEngine', () => {
  let dbManager: DatabaseManager;
  let dbPath: string;

  beforeEach(() => {
    // Create temp database for testing
    dbPath = path.join(__dirname, `test-action-engine-${Date.now()}.db`);
    dbManager = new DatabaseManager(dbPath);
  });

  afterEach(() => {
    dbManager.close();
    if (fs.existsSync(dbPath)) {
      fs.unlinkSync(dbPath);
    }
  });

  const createMockConfig = (overrides?: Partial<SecurityConfig>): SecurityConfig => ({
    enabled: true,
    sensitivity: 'medium',
    owner_ids: ['owner-1', 'owner-2'],
    modules: {
      prompt_injection: { enabled: true },
      command_validator: { enabled: true },
      url_validator: { enabled: true },
      path_validator: { enabled: true },
      secret_detector: { enabled: true },
      content_scanner: { enabled: true },
      injection_validator: { enabled: true },
      exfiltration_detector: { enabled: true },
      code_execution_detector: { enabled: true },
      serialization_detector: { enabled: true }
    },
    actions: {
      [Severity.SAFE]: Action.ALLOW,
      [Severity.LOW]: Action.LOG,
      [Severity.MEDIUM]: Action.WARN,
      [Severity.HIGH]: Action.BLOCK,
      [Severity.CRITICAL]: Action.BLOCK_NOTIFY
    },
    rate_limit: {
      enabled: true,
      max_requests_per_minute: 30,
      lockout_threshold: 5
    },
    notifications: {
      enabled: false,
      channels: {},
      severity_threshold: Severity.HIGH
    },
    logging: {
      enabled: true,
      level: 'info',
      file: '~/.openclaw/logs/security-events.log',
      rotation: 'daily',
      retention_days: 90
    },
    database: {
      path: '.openclaw-sec.db',
      analytics_enabled: true,
      retention_days: 365
    },
    ...overrides
  });

  describe('constructor', () => {
    it('should create instance successfully', () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);
      expect(engine).toBeInstanceOf(ActionEngine);
    });

    it('should throw error if config is null', () => {
      expect(() => new ActionEngine(null as any, dbManager)).toThrow('Configuration is required');
    });

    it('should accept null dbManager for NO_DB mode', () => {
      const config = createMockConfig();
      expect(() => new ActionEngine(config, null as any)).not.toThrow();
    });
  });

  describe('determineAction', () => {
    it('should return ALLOW for SAFE severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.SAFE, 'user-123');

      expect(result.action).toBe(Action.ALLOW);
      expect(result.reasoning).toContain('SAFE');
    });

    it('should return LOG for LOW severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.LOW, 'user-123');

      expect(result.action).toBe(Action.LOG);
      expect(result.reasoning).toContain('LOW');
    });

    it('should return WARN for MEDIUM severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.MEDIUM, 'user-123');

      expect(result.action).toBe(Action.WARN);
      expect(result.reasoning).toContain('MEDIUM');
    });

    it('should return BLOCK for HIGH severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.HIGH, 'user-123');

      expect(result.action).toBe(Action.BLOCK);
      expect(result.reasoning).toContain('HIGH');
    });

    it('should return BLOCK_NOTIFY for CRITICAL severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.CRITICAL, 'user-123');

      expect(result.action).toBe(Action.BLOCK_NOTIFY);
      expect(result.reasoning).toContain('CRITICAL');
    });

    it('should apply custom action overrides from config', async () => {
      const config = createMockConfig({
        actions: {
          [Severity.SAFE]: Action.ALLOW,
          [Severity.LOW]: Action.WARN, // Override: normally LOG
          [Severity.MEDIUM]: Action.BLOCK, // Override: normally WARN
          [Severity.HIGH]: Action.BLOCK_NOTIFY, // Override: normally BLOCK
          [Severity.CRITICAL]: Action.BLOCK_NOTIFY
        }
      });
      const engine = new ActionEngine(config, dbManager);

      const lowResult = await engine.determineAction(Severity.LOW, 'user-123');
      expect(lowResult.action).toBe(Action.WARN);

      const mediumResult = await engine.determineAction(Severity.MEDIUM, 'user-123');
      expect(mediumResult.action).toBe(Action.BLOCK);
    });

    it('should throw error for invalid severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      await expect(engine.determineAction('INVALID' as any, 'user-123')).rejects.toThrow('Invalid severity');
    });

    it('should throw error for null userId', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      await expect(engine.determineAction(Severity.LOW, null as any)).rejects.toThrow('User ID is required');
    });

    it('should throw error for empty userId', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      await expect(engine.determineAction(Severity.LOW, '')).rejects.toThrow('User ID is required');
    });
  });

  describe('reputation-based decisions', () => {
    it('should allow owner users even for high severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.HIGH, 'owner-1');

      expect(result.action).toBe(Action.ALLOW);
      expect(result.reasoning).toContain('owner');
      expect(result.bypassReason).toBe('owner');
    });

    it('should allow allowlisted users for non-critical severities', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      // Add user to allowlist
      dbManager.upsertUserReputation({
        user_id: 'trusted-user',
        trust_score: 100,
        total_requests: 0,
        blocked_attempts: 0,
        is_allowlisted: 1,
        is_blocklisted: 0
      });

      const result = await engine.determineAction(Severity.HIGH, 'trusted-user');

      expect(result.action).toBe(Action.ALLOW);
      expect(result.reasoning).toContain('allowlisted');
      expect(result.bypassReason).toBe('allowlisted');
    });

    it('should not allow allowlisted users for critical severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      // Add user to allowlist
      dbManager.upsertUserReputation({
        user_id: 'trusted-user',
        trust_score: 100,
        total_requests: 0,
        blocked_attempts: 0,
        is_allowlisted: 1,
        is_blocklisted: 0
      });

      const result = await engine.determineAction(Severity.CRITICAL, 'trusted-user');

      expect(result.action).toBe(Action.BLOCK_NOTIFY);
      expect(result.bypassReason).toBeUndefined();
    });

    it('should always block blocklisted users', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      // Add user to blocklist
      dbManager.upsertUserReputation({
        user_id: 'bad-user',
        trust_score: 0,
        total_requests: 0,
        blocked_attempts: 10,
        is_allowlisted: 0,
        is_blocklisted: 1
      });

      const safeResult = await engine.determineAction(Severity.SAFE, 'bad-user');
      expect(safeResult.action).toBe(Action.BLOCK);
      expect(safeResult.reasoning).toContain('blocklisted');

      const lowResult = await engine.determineAction(Severity.LOW, 'bad-user');
      expect(lowResult.action).toBe(Action.BLOCK);
    });

    it('should upgrade action for users with low trust score', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      // User with low trust score
      dbManager.upsertUserReputation({
        user_id: 'suspicious-user',
        trust_score: 15, // Below 20 threshold
        total_requests: 100,
        blocked_attempts: 25,
        is_allowlisted: 0,
        is_blocklisted: 0
      });

      const lowResult = await engine.determineAction(Severity.LOW, 'suspicious-user');
      expect(lowResult.action).toBe(Action.WARN); // Upgraded from LOG
      expect(lowResult.reasoning).toContain('low trust score');
    });

    it('should not upgrade CRITICAL severity', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      // User with low trust score
      dbManager.upsertUserReputation({
        user_id: 'suspicious-user',
        trust_score: 10,
        total_requests: 100,
        blocked_attempts: 50,
        is_allowlisted: 0,
        is_blocklisted: 0
      });

      const result = await engine.determineAction(Severity.CRITICAL, 'suspicious-user');
      expect(result.action).toBe(Action.BLOCK_NOTIFY); // Cannot upgrade beyond BLOCK_NOTIFY
    });
  });

  describe('edge cases', () => {
    it('should handle user with no reputation record', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.MEDIUM, 'new-user');

      expect(result.action).toBe(Action.WARN);
      expect(result.reasoning).toContain('MEDIUM');
    });

    it('should handle missing actions in config gracefully', async () => {
      const config = createMockConfig();
      // Remove actions config
      delete (config as any).actions;

      const engine = new ActionEngine(config, dbManager);

      // Should use default mappings
      const result = await engine.determineAction(Severity.HIGH, 'user-123');
      expect(result.action).toBe(Action.BLOCK);
    });

    it('should handle database errors gracefully', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      // Close database to trigger error
      dbManager.close();

      // Should not throw, should use default behavior
      await expect(engine.determineAction(Severity.MEDIUM, 'user-123')).resolves.toBeDefined();
    });
  });

  describe('reasoning generation', () => {
    it('should include severity in reasoning', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.HIGH, 'user-123');

      expect(result.reasoning).toContain('HIGH');
      expect(result.reasoning.toLowerCase()).toContain('block');
    });

    it('should include trust score in reasoning when applicable', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      dbManager.upsertUserReputation({
        user_id: 'user-123',
        trust_score: 15,
        total_requests: 100,
        blocked_attempts: 25,
        is_allowlisted: 0,
        is_blocklisted: 0
      });

      const result = await engine.determineAction(Severity.LOW, 'user-123');

      expect(result.reasoning).toContain('trust score');
    });

    it('should provide clear reasoning for all decision factors', async () => {
      const config = createMockConfig();
      const engine = new ActionEngine(config, dbManager);

      const result = await engine.determineAction(Severity.MEDIUM, 'user-123');

      expect(result.reasoning).toBeTruthy();
      expect(result.reasoning.length).toBeGreaterThan(10);
      expect(result.action).toBeDefined();
    });
  });
});

import { describe, it, expect, beforeEach, afterEach, jest } from '@jest/globals';
import { AsyncQueue, AsyncQueueOptions } from '../async-queue';

describe('AsyncQueue', () => {
  let queue: AsyncQueue;

  afterEach(() => {
    if (queue) {
      queue.stop();
    }
  });

  describe('Basic functionality', () => {
    it('should create a queue with default options', () => {
      queue = new AsyncQueue({
        onBatch: jest.fn() as any,
      });

      expect(queue.size()).toBe(0);
    });

    it('should create a queue with custom options', () => {
      const options: AsyncQueueOptions = {
        batchSize: 10,
        flushInterval: 50,
        maxQueueSize: 100,
        onBatch: jest.fn() as any,
      };

      queue = new AsyncQueue(options);
      expect(queue.size()).toBe(0);
    });

    it('should throw error if onBatch is not provided', () => {
      expect(() => {
        // @ts-expect-error - Testing missing required option
        queue = new AsyncQueue({});
      }).toThrow('onBatch callback is required');
    });

    it('should throw error if onBatch is not a function', () => {
      expect(() => {
        // @ts-expect-error - Testing invalid onBatch type
        queue = new AsyncQueue({ onBatch: 'not-a-function' });
      }).toThrow('onBatch must be a function');
    });

    it('should validate batchSize is positive', () => {
      expect(() => {
        queue = new AsyncQueue({
          batchSize: 0,
          onBatch: jest.fn() as any,
        });
      }).toThrow('batchSize must be greater than 0');
    });

    it('should validate flushInterval is positive', () => {
      expect(() => {
        queue = new AsyncQueue({
          flushInterval: -1,
          onBatch: jest.fn() as any,
        });
      }).toThrow('flushInterval must be greater than 0');
    });

    it('should validate maxQueueSize is positive', () => {
      expect(() => {
        queue = new AsyncQueue({
          maxQueueSize: 0,
          onBatch: jest.fn() as any,
        });
      }).toThrow('maxQueueSize must be greater than 0');
    });
  });

  describe('Enqueue and size', () => {
    it('should enqueue tasks and track size', () => {
      const onBatch = jest.fn() as any;
      queue = new AsyncQueue({
        batchSize: 10,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      expect(queue.size()).toBe(1);

      queue.enqueue({ id: 2 });
      queue.enqueue({ id: 3 });
      expect(queue.size()).toBe(3);
    });

    it('should return queue size after processing', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 2,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      // Wait for batch to process
      await new Promise((resolve) => setTimeout(resolve, 10));

      expect(queue.size()).toBe(0);
    });
  });

  describe('Batch processing', () => {
    it('should process batch when batch size is reached', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 3,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });
      expect(onBatch).not.toHaveBeenCalled();

      queue.enqueue({ id: 3 });

      // Wait for async processing
      await new Promise((resolve) => setTimeout(resolve, 10));

      expect(onBatch).toHaveBeenCalledTimes(1);
      expect(onBatch).toHaveBeenCalledWith([{ id: 1 }, { id: 2 }, { id: 3 }]);
      expect(queue.size()).toBe(0);
    });

    it('should process multiple batches', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 2,
        onBatch,
      });

      // First batch
      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      await new Promise((resolve) => setTimeout(resolve, 10));

      // Second batch
      queue.enqueue({ id: 3 });
      queue.enqueue({ id: 4 });

      await new Promise((resolve) => setTimeout(resolve, 10));

      expect(onBatch).toHaveBeenCalledTimes(2);
      expect(onBatch).toHaveBeenNthCalledWith(1, [{ id: 1 }, { id: 2 }]);
      expect(onBatch).toHaveBeenNthCalledWith(2, [{ id: 3 }, { id: 4 }]);
    });

    it('should process tasks asynchronously without blocking', async () => {
      const processedTasks: number[] = [];
      const onBatch = (jest.fn() as any).mockImplementation(async (tasks: any[]) => {
        await new Promise((resolve) => setTimeout(resolve, 20));
        tasks.forEach((task) => processedTasks.push(task.id));
      });

      queue = new AsyncQueue({
        batchSize: 2,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      // Should not block
      expect(processedTasks).toEqual([]);

      // Wait for processing
      await new Promise((resolve) => setTimeout(resolve, 50));

      expect(processedTasks).toEqual([1, 2]);
    });
  });

  describe('Flush interval', () => {
    it('should process tasks after flush interval', async () => {
      jest.useFakeTimers();

      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 10,
        flushInterval: 100,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      expect(onBatch).not.toHaveBeenCalled();

      // Advance timers to trigger one interval
      jest.advanceTimersByTime(100);
      await Promise.resolve(); // Let microtasks run

      expect(onBatch).toHaveBeenCalledWith([{ id: 1 }, { id: 2 }]);

      queue.stop();
      jest.useRealTimers();
    });

    it('should continue processing at intervals', async () => {
      // Use real timers for this test since we need actual async behavior
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 10,
        flushInterval: 50,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      await new Promise((resolve) => setTimeout(resolve, 60));

      expect(onBatch).toHaveBeenCalledTimes(1);
      expect(onBatch).toHaveBeenNthCalledWith(1, [{ id: 1 }]);

      queue.enqueue({ id: 2 });
      await new Promise((resolve) => setTimeout(resolve, 60));

      expect(onBatch).toHaveBeenCalledTimes(2);
      expect(onBatch).toHaveBeenNthCalledWith(2, [{ id: 2 }]);
    });

    it('should not process empty queue on interval', async () => {
      jest.useFakeTimers();

      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 10,
        flushInterval: 100,
        onBatch,
      });

      jest.advanceTimersByTime(100);
      await Promise.resolve(); // Let microtasks run

      expect(onBatch).not.toHaveBeenCalled();

      queue.stop();
      jest.useRealTimers();
    });
  });

  describe('Manual flush', () => {
    it('should flush all remaining tasks', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 10,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });
      queue.enqueue({ id: 3 });

      await queue.flush();

      expect(onBatch).toHaveBeenCalledWith([{ id: 1 }, { id: 2 }, { id: 3 }]);
      expect(queue.size()).toBe(0);
    });

    it('should not process if queue is empty', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 10,
        onBatch,
      });

      await queue.flush();

      expect(onBatch).not.toHaveBeenCalled();
    });

    it('should wait for flush to complete', async () => {
      const processedTasks: number[] = [];
      const onBatch = (jest.fn() as any).mockImplementation(async (tasks: any[]) => {
        await new Promise((resolve) => setTimeout(resolve, 20));
        tasks.forEach((task) => processedTasks.push(task.id));
      });

      queue = new AsyncQueue({
        batchSize: 10,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      await queue.flush();

      expect(processedTasks).toEqual([1, 2]);
    });
  });

  describe('Queue overflow', () => {
    it('should drop oldest tasks when max queue size is exceeded', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 100,
        maxQueueSize: 5,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });
      queue.enqueue({ id: 3 });
      queue.enqueue({ id: 4 });
      queue.enqueue({ id: 5 });

      expect(queue.size()).toBe(5);

      // This should drop task 1
      queue.enqueue({ id: 6 });
      expect(queue.size()).toBe(5);

      // This should drop task 2
      queue.enqueue({ id: 7 });
      expect(queue.size()).toBe(5);

      await queue.flush();

      expect(onBatch).toHaveBeenCalledWith([
        { id: 3 },
        { id: 4 },
        { id: 5 },
        { id: 6 },
        { id: 7 },
      ]);
    });

    it('should handle overflow with batch processing', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 3,
        maxQueueSize: 5,
        onBatch,
      });

      // Fill queue
      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });
      queue.enqueue({ id: 3 });

      // This triggers batch processing
      await new Promise((resolve) => setTimeout(resolve, 10));

      // Now add more to test overflow
      // When we add these 5, the 3rd one triggers another batch
      queue.enqueue({ id: 4 }); // size=1
      queue.enqueue({ id: 5 }); // size=2
      queue.enqueue({ id: 6 }); // size=3, triggers batch processing
      queue.enqueue({ id: 7 }); // size=1
      queue.enqueue({ id: 8 }); // size=2

      // After second batch triggered on id:6, only 7,8 remain
      await new Promise((resolve) => setTimeout(resolve, 10));
      expect(queue.size()).toBe(2);

      await queue.flush();

      expect(onBatch).toHaveBeenCalledTimes(3);
      expect(onBatch).toHaveBeenNthCalledWith(1, [{ id: 1 }, { id: 2 }, { id: 3 }]);
      expect(onBatch).toHaveBeenNthCalledWith(2, [{ id: 4 }, { id: 5 }, { id: 6 }]);
      expect(onBatch).toHaveBeenNthCalledWith(3, [{ id: 7 }, { id: 8 }]);
    });
  });

  describe('Error handling', () => {
    it('should handle errors in onBatch callback', async () => {
      const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
      const onBatch = (jest.fn() as any).mockRejectedValue(new Error('Batch processing failed'));

      queue = new AsyncQueue({
        batchSize: 2,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      await new Promise((resolve) => setTimeout(resolve, 10));

      expect(onBatch).toHaveBeenCalled();
      expect(consoleErrorSpy).toHaveBeenCalledWith(
        'Error processing batch:',
        expect.any(Error)
      );

      consoleErrorSpy.mockRestore();
    });

    it('should continue processing after error', async () => {
      const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
      let callCount = 0;
      const onBatch = (jest.fn() as any).mockImplementation(() => {
        callCount++;
        if (callCount === 1) {
          return Promise.reject(new Error('First batch failed'));
        }
        return Promise.resolve();
      });

      queue = new AsyncQueue({
        batchSize: 2,
        onBatch,
      });

      // First batch - will fail
      queue.enqueue({ id: 1 });
      queue.enqueue({ id: 2 });

      await new Promise((resolve) => setTimeout(resolve, 10));

      // Second batch - should succeed
      queue.enqueue({ id: 3 });
      queue.enqueue({ id: 4 });

      await new Promise((resolve) => setTimeout(resolve, 10));

      expect(onBatch).toHaveBeenCalledTimes(2);
      expect(consoleErrorSpy).toHaveBeenCalledTimes(1);

      consoleErrorSpy.mockRestore();
    });

    it('should handle errors during flush', async () => {
      const consoleErrorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
      const onBatch = (jest.fn() as any).mockRejectedValue(new Error('Flush failed'));

      queue = new AsyncQueue({
        batchSize: 10,
        onBatch,
      });

      queue.enqueue({ id: 1 });

      await expect(queue.flush()).rejects.toThrow('Flush failed');

      consoleErrorSpy.mockRestore();
    });
  });

  describe('Stop and cleanup', () => {
    it('should stop the timer', () => {
      const onBatch = jest.fn() as any;
      queue = new AsyncQueue({
        batchSize: 10,
        flushInterval: 100,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.stop();

      // Timer should be stopped, so this should not trigger processing
      // (difficult to test directly, but stop should clear the interval)
      expect(queue.size()).toBe(1);
    });

    it('should allow stop to be called multiple times', () => {
      const onBatch = jest.fn() as any;
      queue = new AsyncQueue({
        batchSize: 10,
        onBatch,
      });

      expect(() => {
        queue.stop();
        queue.stop();
        queue.stop();
      }).not.toThrow();
    });

    it('should not process after stop is called', async () => {
      jest.useFakeTimers();

      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 10,
        flushInterval: 100,
        onBatch,
      });

      queue.enqueue({ id: 1 });
      queue.stop();

      jest.advanceTimersByTime(200);
      await jest.runAllTimersAsync();

      expect(onBatch).not.toHaveBeenCalled();

      jest.useRealTimers();
    });
  });

  describe('Edge cases', () => {
    it('should handle tasks with undefined or null values', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 3,
        onBatch,
      });

      queue.enqueue(null);
      queue.enqueue(undefined);
      queue.enqueue({ id: 1 });

      await queue.flush();

      expect(onBatch).toHaveBeenCalledWith([null, undefined, { id: 1 }]);
    });

    it('should handle complex task objects', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 2,
        onBatch,
      });

      const complexTask = {
        id: 1,
        nested: { data: { value: 'test' } },
        array: [1, 2, 3],
        fn: () => 'test',
      };

      queue.enqueue(complexTask);
      queue.enqueue({ id: 2 });

      await queue.flush();

      expect(onBatch).toHaveBeenCalledWith([complexTask, { id: 2 }]);
    });

    it('should handle rapid enqueuing', async () => {
      const onBatch = (jest.fn() as any).mockResolvedValue(undefined);
      queue = new AsyncQueue({
        batchSize: 100,
        onBatch,
      });

      // Rapidly enqueue 1000 tasks
      for (let i = 0; i < 1000; i++) {
        queue.enqueue({ id: i });
      }

      await queue.flush();

      expect(onBatch).toHaveBeenCalled();
      // Should have processed all tasks in one batch (or multiple if batch size is hit)
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from '@jest/globals';
import * as fs from 'fs';
import * as path from 'path';
import { ConfigManager } from '../config-manager';
import type { SecurityConfig } from '../../types';

describe('ConfigManager', () => {
  const testConfigDir = path.join(__dirname, 'test-configs');
  const testConfigPath = path.join(testConfigDir, 'test-config.yaml');

  beforeEach(() => {
    // Create test directory
    if (!fs.existsSync(testConfigDir)) {
      fs.mkdirSync(testConfigDir, { recursive: true });
    }
  });

  afterEach(() => {
    // Clean up test files
    if (fs.existsSync(testConfigPath)) {
      fs.unlinkSync(testConfigPath);
    }
    if (fs.existsSync(testConfigDir)) {
      fs.rmdirSync(testConfigDir);
    }
  });

  describe('getDefaultConfig', () => {
    it('should return default configuration', () => {
      const config = ConfigManager.getDefaultConfig();

      expect(config).toHaveProperty('enabled');
      expect(config).toHaveProperty('database');
      expect(config).toHaveProperty('modules');
      expect(config.database.path).toBe('.openclaw-sec.db');
      expect(config.sensitivity).toBe('medium');
    });
  });

  describe('load', () => {
    it('should return default config when file does not exist', async () => {
      const config = await ConfigManager.load('nonexistent.yaml');
      const defaultConfig = ConfigManager.getDefaultConfig();

      expect(config).toEqual(defaultConfig);
    });

    it('should load and merge config from YAML file', async () => {
      const userConfig = `
openclaw_security:
  database:
    path: custom.db
  sensitivity: strict
  modules:
    prompt_injection:
      enabled: true
      sensitivity: paranoid
`;
      fs.writeFileSync(testConfigPath, userConfig);

      const config = await ConfigManager.load(testConfigPath);

      expect(config.database.path).toBe('custom.db');
      expect(config.sensitivity).toBe('strict');
      expect(config.modules.prompt_injection.sensitivity).toBe('paranoid');
    });

    it('should merge user config with defaults', async () => {
      const userConfig = `
openclaw_security:
  database:
    path: custom.db
`;
      fs.writeFileSync(testConfigPath, userConfig);

      const config = await ConfigManager.load(testConfigPath);

      expect(config.database.path).toBe('custom.db');
      expect(config).toHaveProperty('modules');
      expect(config).toHaveProperty('actions');
    });

    it('should handle invalid YAML gracefully', async () => {
      const invalidYaml = `
openclaw_security:
  database:
    path: [invalid: yaml
`;
      fs.writeFileSync(testConfigPath, invalidYaml);

      await expect(ConfigManager.load(testConfigPath)).rejects.toThrow();
    });

    it('should validate sensitivity levels', async () => {
      const invalidConfig = `
openclaw_security:
  sensitivity: invalid_level
`;
      fs.writeFileSync(testConfigPath, invalidConfig);

      await expect(ConfigManager.load(testConfigPath)).rejects.toThrow('Invalid sensitivity level');
    });

    it('should validate actions', async () => {
      const invalidConfig = `
openclaw_security:
  actions:
    HIGH: invalid_action
`;
      fs.writeFileSync(testConfigPath, invalidConfig);

      await expect(ConfigManager.load(testConfigPath)).rejects.toThrow('Invalid action');
    });
  });

  describe('deepMerge', () => {
    it('should merge nested objects', () => {
      const target = {
        a: { b: 1, c: 2 },
        d: 3
      };
      const source = {
        a: { b: 10, e: 4 },
        f: 5
      };

      const result = ConfigManager.deepMerge(target, source);

      expect(result).toEqual({
        a: { b: 10, c: 2, e: 4 },
        d: 3,
        f: 5
      });
    });

    it('should replace arrays instead of merging', () => {
      const target = {
        rules: [{ pattern: 'old' }]
      };
      const source = {
        rules: [{ pattern: 'new' }]
      };

      const result = ConfigManager.deepMerge(target, source);

      expect(result.rules).toEqual([{ pattern: 'new' }]);
    });
  });

  describe('validateConfig', () => {
    it('should accept valid config', () => {
      const validConfig = ConfigManager.getDefaultConfig();
      expect(() => ConfigManager.validateConfig(validConfig)).not.toThrow();
    });

    it('should reject invalid sensitivity level', () => {
      const invalidConfig: any = {
        sensitivity: 'invalid',
        actions: {},
        modules: {}
      };

      expect(() => ConfigManager.validateConfig(invalidConfig)).toThrow('Invalid sensitivity level');
    });

    it('should reject invalid action', () => {
      const defaultConfig = ConfigManager.getDefaultConfig();
      const invalidConfig: any = {
        ...defaultConfig,
        actions: {
          HIGH: 'invalid_action'
        }
      };

      expect(() => ConfigManager.validateConfig(invalidConfig)).toThrow('Invalid action');
    });
  });
});

import { DatabaseManager, DatabaseError } from '../database-manager';
import { Severity, Action } from '../../types';
import * as fs from 'fs';
import * as path from 'path';

describe('DatabaseManager', () => {
  let db: DatabaseManager;
  let testDbPath: string;

  beforeEach(() => {
    testDbPath = path.join(__dirname, 'test.db');
    if (fs.existsSync(testDbPath)) {
      fs.unlinkSync(testDbPath);
    }
    db = new DatabaseManager(testDbPath);
  });

  afterEach(() => {
    db.close();
    if (fs.existsSync(testDbPath)) {
      fs.unlinkSync(testDbPath);
    }
  });

  test('initializes database with correct schema', () => {
    const tables = db.getTables();
    expect(tables).toContain('security_events');
    expect(tables).toContain('rate_limits');
    expect(tables).toContain('user_reputation');
    expect(tables).toContain('attack_patterns');
    expect(tables).toContain('notifications_log');
  });

  test('inserts and retrieves security event', () => {
    const event = {
      event_type: 'prompt_injection',
      severity: Severity.HIGH,
      action_taken: Action.BLOCK,
      user_id: 'user123',
      session_id: 'session456',
      input_text: 'ignore previous instructions',
      patterns_matched: JSON.stringify(['instruction_override']),
      fingerprint: 'abc123',
      module: 'prompt_injection',
      metadata: JSON.stringify({})
    };

    const id = db.insertEvent(event);
    expect(id).toBeGreaterThan(0);

    const retrieved = db.getEventById(id);
    expect(retrieved).toBeDefined();
    expect(retrieved?.severity).toBe(Severity.HIGH);
  });

  test('retrieves events by user ID', () => {
    const event1 = {
      event_type: 'prompt_injection',
      severity: Severity.HIGH,
      action_taken: Action.BLOCK,
      user_id: 'user123',
      session_id: 'session456',
      input_text: 'test input 1',
      patterns_matched: JSON.stringify(['pattern1']),
      fingerprint: 'hash1',
      module: 'prompt_injection',
      metadata: JSON.stringify({})
    };

    const event2 = {
      event_type: 'command_injection',
      severity: Severity.MEDIUM,
      action_taken: Action.WARN,
      user_id: 'user123',
      session_id: 'session789',
      input_text: 'test input 2',
      patterns_matched: JSON.stringify(['pattern2']),
      fingerprint: 'hash2',
      module: 'command_validator',
      metadata: JSON.stringify({})
    };

    db.insertEvent(event1);
    db.insertEvent(event2);

    const events = db.getEventsByUserId('user123');
    expect(events).toHaveLength(2);
    // Events should be sorted by timestamp descending
    expect(events.some(e => e.event_type === 'prompt_injection')).toBe(true);
    expect(events.some(e => e.event_type === 'command_injection')).toBe(true)
  });

  test('upserts and retrieves rate limit', () => {
    const rateLimit = {
      user_id: 'user123',
      request_count: 5,
      window_start: new Date().toISOString(),
      lockout_until: undefined,
      failed_attempts: 0
    };

    db.upsertRateLimit(rateLimit);

    const retrieved = db.getRateLimitByUserId('user123');
    expect(retrieved).toBeDefined();
    expect(retrieved?.request_count).toBe(5);
    expect(retrieved?.failed_attempts).toBe(0);

    // Test update
    const updated = {
      user_id: 'user123',
      request_count: 10,
      window_start: new Date().toISOString(),
      lockout_until: new Date().toISOString(),
      failed_attempts: 3
    };

    db.upsertRateLimit(updated);
    const retrievedUpdated = db.getRateLimitByUserId('user123');
    expect(retrievedUpdated?.request_count).toBe(10);
    expect(retrievedUpdated?.failed_attempts).toBe(3);
  });

  test('upserts and retrieves user reputation', () => {
    const reputation = {
      user_id: 'user123',
      trust_score: 85.5,
      total_requests: 10,
      blocked_attempts: 2,
      last_violation: undefined,
      is_allowlisted: 0,
      is_blocklisted: 0,
      notes: undefined
    };

    db.upsertUserReputation(reputation);

    const retrieved = db.getUserReputation('user123');
    expect(retrieved).toBeDefined();
    expect(retrieved?.trust_score).toBe(85.5);
    expect(retrieved?.total_requests).toBe(10);
    expect(retrieved?.blocked_attempts).toBe(2);
  });

  test('upserts and retrieves attack patterns', () => {
    const pattern = {
      pattern: 'ignore previous instructions',
      category: 'prompt_injection',
      severity: Severity.HIGH,
      language: 'en',
      times_matched: 1,
      last_matched: new Date().toISOString(),
      is_custom: 0,
      enabled: 1
    };

    const id = db.upsertAttackPattern(pattern);
    expect(id).toBeGreaterThan(0);

    const retrieved = db.getAttackPatternByPattern('ignore previous instructions');
    expect(retrieved).toBeDefined();
    expect(retrieved?.pattern).toBe('ignore previous instructions');
    expect(retrieved?.times_matched).toBe(1);
    expect(retrieved?.language).toBe('en');

    // Test update
    db.upsertAttackPattern({ ...pattern, times_matched: 5 });
    const updated = db.getAttackPatternByPattern('ignore previous instructions');
    expect(updated?.times_matched).toBe(5);
  });

  test('retrieves attack patterns by category', () => {
    const pattern1 = {
      pattern: 'pattern 1',
      category: 'prompt_injection',
      severity: Severity.HIGH,
      language: 'en',
      times_matched: 5,
      last_matched: new Date().toISOString(),
      is_custom: 0,
      enabled: 1
    };

    const pattern2 = {
      pattern: 'pattern 2',
      category: 'prompt_injection',
      severity: Severity.MEDIUM,
      language: 'en',
      times_matched: 3,
      last_matched: new Date().toISOString(),
      is_custom: 0,
      enabled: 1
    };

    db.upsertAttackPattern(pattern1);
    db.upsertAttackPattern(pattern2);

    const patterns = db.getAttackPatternsByCategory('prompt_injection');
    expect(patterns).toHaveLength(2);
    expect(patterns[0].times_matched).toBe(5); // Sorted by times_matched DESC
  });

  test('inserts and retrieves notification logs', () => {
    const event = {
      event_type: 'prompt_injection',
      severity: Severity.HIGH,
      action_taken: Action.BLOCK,
      user_id: 'user123',
      session_id: 'session456',
      input_text: 'test',
      patterns_matched: JSON.stringify([]),
      fingerprint: 'hash',
      module: 'prompt_injection',
      metadata: JSON.stringify({})
    };

    const eventId = db.insertEvent(event);

    const notificationLog = {
      channel: 'slack',
      severity: Severity.HIGH,
      message: 'High severity attack detected',
      delivery_status: 'success',
      event_id: eventId
    };

    const logId = db.insertNotificationLog(notificationLog);
    expect(logId).toBeGreaterThan(0);

    const logs = db.getNotificationLogsByEventId(eventId);
    expect(logs).toHaveLength(1);
    expect(logs[0].channel).toBe('slack');
    expect(logs[0].delivery_status).toBe('success');
    expect(logs[0].severity).toBe(Severity.HIGH);
    expect(logs[0].message).toBe('High severity attack detected');
  });

  test('deletes old events', () => {
    const event = {
      event_type: 'prompt_injection',
      severity: Severity.HIGH,
      action_taken: Action.BLOCK,
      user_id: 'user123',
      session_id: 'session456',
      input_text: 'test',
      patterns_matched: JSON.stringify([]),
      fingerprint: 'hash',
      module: 'prompt_injection',
      metadata: JSON.stringify({})
    };

    db.insertEvent(event);

    // Delete events older than 0 days should delete nothing (events just created)
    const deleted = db.deleteOldEvents(0);
    expect(deleted).toBe(0);

    const events = db.getEventsByUserId('user123');
    expect(events).toHaveLength(1);
  });

  describe('Error Handling', () => {
    test('throws DatabaseError on invalid severity', () => {
      const event = {
        event_type: 'test',
        severity: 'INVALID' as Severity,
        action_taken: Action.BLOCK,
        user_id: 'user123',
        session_id: 'session456',
        input_text: 'test',
        patterns_matched: JSON.stringify([]),
        fingerprint: 'hash',
        module: 'test',
        metadata: JSON.stringify({})
      };

      expect(() => db.insertEvent(event)).toThrow(DatabaseError);
      expect(() => db.insertEvent(event)).toThrow(/Invalid severity/);
    });

    test('throws DatabaseError on invalid action', () => {
      const event = {
        event_type: 'test',
        severity: Severity.HIGH,
        action_taken: 'INVALID' as Action,
        user_id: 'user123',
        session_id: 'session456',
        input_text: 'test',
        patterns_matched: JSON.stringify([]),
        fingerprint: 'hash',
        module: 'test',
        metadata: JSON.stringify({})
      };

      expect(() => db.insertEvent(event)).toThrow(DatabaseError);
      expect(() => db.insertEvent(event)).toThrow(/Invalid action/);
    });

    test('throws DatabaseError on missing required fields', () => {
      const event = {
        event_type: '',
        severity: Severity.HIGH,
        action_taken: Action.BLOCK,
        user_id: 'user123',
        session_id: 'session456',
        input_text: 'test',
        patterns_matched: JSON.stringify([]),
        fingerprint: 'hash',
        module: 'test',
        metadata: JSON.stringify({})
      };

      expect(() => db.insertEvent(event)).toThrow(DatabaseError);
      expect(() => db.insertEvent(event)).toThrow(/event_type is required/);
    });

    test('throws DatabaseError on negative limit', () => {
      expect(() => db.getEventsByUserId('user123', -1)).toThrow(DatabaseError);
      expect(() => db.getEventsByUserId('user123', -1)).toThrow(/limit must be a positive integer/);
    });

    test('throws DatabaseError on invalid daysToKeep in deleteOldEvents', () => {
      expect(() => db.deleteOldEvents(-5)).toThrow(DatabaseError);
      expect(() => db.deleteOldEvents(-5)).toThrow(/daysToKeep must be a positive integer/);

      expect(() => db.deleteOldEvents(1.5)).toThrow(DatabaseError);
      expect(() => db.deleteOldEvents(1.5)).toThrow(/daysToKeep must be a positive integer/);
    });

    test('throws DatabaseError when operating on closed database', () => {
      db.close();

      expect(() => db.getTables()).toThrow(DatabaseError);
      expect(() => db.getTables()).toThrow(/Database connection is closed/);
    });

    test('throws DatabaseError on invalid trust_score', () => {
      const reputation = {
        user_id: 'user123',
        trust_score: -10,
        total_requests: 10,
        blocked_attempts: 0,
        is_allowlisted: 0,
        is_blocklisted: 0
      };

      expect(() => db.upsertUserReputation(reputation)).toThrow(DatabaseError);
      expect(() => db.upsertUserReputation(reputation)).toThrow(/trust_score must be a non-negative number/);
    });

    test('throws DatabaseError on invalid boolean flags', () => {
      const reputation = {
        user_id: 'user123',
        trust_score: 100,
        total_requests: 10,
        blocked_attempts: 0,
        is_allowlisted: 2, // Invalid, should be 0 or 1
        is_blocklisted: 0
      };

      expect(() => db.upsertUserReputation(reputation)).toThrow(DatabaseError);
      expect(() => db.upsertUserReputation(reputation)).toThrow(/is_allowlisted must be 0 or 1/);
    });

    test('enforces foreign key constraints', () => {
      const notificationLog = {
        channel: 'slack',
        severity: Severity.HIGH,
        message: 'Test',
        delivery_status: 'success',
        event_id: 99999 // Non-existent event ID
      };

      // With foreign keys enabled, this should fail
      expect(() => db.insertNotificationLog(notificationLog)).toThrow(DatabaseError);
    });

    test('validates attack pattern fields', () => {
      const pattern = {
        pattern: 'test pattern',
        category: 'test',
        severity: Severity.HIGH,
        language: 'en',
        times_matched: -1, // Invalid negative value
        is_custom: 0,
        enabled: 1
      };

      expect(() => db.upsertAttackPattern(pattern)).toThrow(DatabaseError);
      expect(() => db.upsertAttackPattern(pattern)).toThrow(/times_matched must be a positive integer/);
    });

    test('validates rate limit fields', () => {
      const rateLimit = {
        user_id: 'user123',
        request_count: -5, // Invalid negative value
        window_start: new Date().toISOString(),
        failed_attempts: 0
      };

      expect(() => db.upsertRateLimit(rateLimit)).toThrow(DatabaseError);
      expect(() => db.upsertRateLimit(rateLimit)).toThrow(/request_count must be a positive integer/);
    });
  });
});

import { Logger, LogLevel } from '../logger';
import { Severity, Action } from '../../types';
import * as fs from 'fs';
import * as path from 'path';

describe('Logger', () => {
  let testLogDir: string;

  beforeEach(() => {
    // Create temp directory for test logs
    testLogDir = path.join(__dirname, `test-logs-${Date.now()}`);
    if (!fs.existsSync(testLogDir)) {
      fs.mkdirSync(testLogDir, { recursive: true });
    }
  });

  afterEach(async () => {
    // Small delay to ensure all writes complete
    await new Promise(resolve => setTimeout(resolve, 100));

    // Clean up test logs
    if (fs.existsSync(testLogDir)) {
      try {
        const files = fs.readdirSync(testLogDir);
        files.forEach(file => {
          try {
            fs.unlinkSync(path.join(testLogDir, file));
          } catch (e) {
            // Ignore cleanup errors
          }
        });
        fs.rmdirSync(testLogDir);
      } catch (e) {
        // Ignore cleanup errors
      }
    }
  });

  describe('constructor', () => {
    it('should create logger instance successfully', () => {
      const logFile = path.join(testLogDir, 'test.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO
      });
      expect(logger).toBeInstanceOf(Logger);
      logger.stop();
    });

    it('should throw error if filePath is missing', () => {
      expect(() => new Logger({
        filePath: '',
        level: LogLevel.INFO
      })).toThrow('Log file path is required');
    });

    it('should create log file directory if it does not exist', () => {
      const nestedDir = path.join(testLogDir, 'nested', 'dir');
      const logFile = path.join(nestedDir, 'test.log');

      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO
      });

      expect(fs.existsSync(nestedDir)).toBe(true);
      logger.stop();
    });
  });

  describe('log levels', () => {
    it('should log info messages when level is INFO', async () => {
      const logFile = path.join(testLogDir, 'info.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        batchSize: 1
      });

      logger.info('Info message', { userId: 'user-123' });
      logger.stop(); // Stop will flush

      await new Promise(resolve => setTimeout(resolve, 150));

      expect(fs.existsSync(logFile)).toBe(true);
      const content = fs.readFileSync(logFile, 'utf8');
      expect(content).toContain('INFO');
      expect(content).toContain('Info message');
    });

    it('should log warning messages', async () => {
      const logFile = path.join(testLogDir, 'warn.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.WARN,
        batchSize: 1
      });

      logger.warn('Warning message', { severity: Severity.MEDIUM });
      logger.stop();

      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      expect(content).toContain('WARN');
      expect(content).toContain('Warning message');
    });

    it('should log error messages', async () => {
      const logFile = path.join(testLogDir, 'error.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.ERROR,
        batchSize: 1
      });

      logger.error('Error message', { error: 'Something failed' });
      logger.stop();

      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      expect(content).toContain('ERROR');
      expect(content).toContain('Error message');
    });

    it('should not log messages below configured level', async () => {
      const logFile = path.join(testLogDir, 'filtered.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.ERROR, // Only log ERROR
        batchSize: 1
      });

      logger.debug('Debug message');
      logger.info('Info message');
      logger.warn('Warn message');
      logger.error('Error message');
      logger.stop();

      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      expect(content).not.toContain('DEBUG');
      expect(content).not.toContain('INFO');
      expect(content).not.toContain('WARN');
      expect(content).toContain('ERROR');
    });
  });

  describe('logSecurityEvent', () => {
    it('should log structured security event', async () => {
      const logFile = path.join(testLogDir, 'security.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        batchSize: 1
      });

      logger.logSecurityEvent({
        severity: Severity.HIGH,
        action: Action.BLOCK,
        userId: 'user-123',
        module: 'prompt_injection',
        fingerprint: 'fp-123',
        message: 'Prompt injection detected'
      });

      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      const logEntry = JSON.parse(content.trim());

      expect(logEntry.level).toBe('INFO');
      expect(logEntry.severity).toBe(Severity.HIGH);
      expect(logEntry.action).toBe(Action.BLOCK);
      expect(logEntry.userId).toBe('user-123');
      expect(logEntry.module).toBe('prompt_injection');
      expect(logEntry.fingerprint).toBe('fp-123');
    });

    it('should include metadata in security event', async () => {
      const logFile = path.join(testLogDir, 'security-meta.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        batchSize: 1
      });

      logger.logSecurityEvent({
        severity: Severity.CRITICAL,
        action: Action.BLOCK_NOTIFY,
        userId: 'user-456',
        module: 'command_validator',
        fingerprint: 'fp-456',
        message: 'Command injection attempt',
        metadata: {
          command: 'rm -rf /',
          patternId: 'cmd-inject-001'
        }
      });

      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      const logEntry = JSON.parse(content.trim());

      expect(logEntry.metadata).toBeDefined();
      expect(logEntry.metadata.command).toBe('rm -rf /');
      expect(logEntry.metadata.patternId).toBe('cmd-inject-001');
    });
  });

  describe('buffered writes', () => {
    it('should buffer writes and flush manually', async () => {
      const logFile = path.join(testLogDir, 'buffered.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        batchSize: 1
      });

      // Log multiple messages
      logger.info('Message 1');
      logger.info('Message 2');
      logger.info('Message 3');

      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      const lines = content.trim().split('\n');

      expect(lines.length).toBe(3);
    });
  });

  describe('log rotation', () => {
    it('should rotate log file when it exceeds max size', async () => {
      const logFile = path.join(testLogDir, 'rotate.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        maxFileSize: 500, // 500 bytes - very small for testing
        batchSize: 1
      });

      // Write enough data to trigger rotation
      for (let i = 0; i < 10; i++) {
        logger.info(`This is a test message that will help us exceed the max file size ${i}`, {
          data: 'x'.repeat(50)
        });
      }

      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 200));

      // Check that rotated file exists
      const files = fs.readdirSync(testLogDir);
      const rotatedFiles = files.filter(f => f.startsWith('rotate.log.'));

      expect(rotatedFiles.length).toBeGreaterThan(0);
    });

    it('should keep only specified number of rotated files', async () => {
      const logFile = path.join(testLogDir, 'rotate-limit.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        maxFileSize: 300,
        maxRotatedFiles: 3,
        batchSize: 1
      });

      // Write enough to create multiple rotations
      for (let i = 0; i < 20; i++) {
        logger.info(`Message ${i}`, { data: 'x'.repeat(100) });
      }

      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 200));

      const files = fs.readdirSync(testLogDir);
      const rotatedFiles = files.filter(f => f.startsWith('rotate-limit.log.'));

      // Should keep max 3 rotated files
      expect(rotatedFiles.length).toBeLessThanOrEqual(3);
    });
  });

  describe('JSON formatting', () => {
    it('should write valid JSON for each log entry', async () => {
      const logFile = path.join(testLogDir, 'json.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        batchSize: 1
      });

      logger.info('Test message', { key: 'value', number: 42 });
      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      const logEntry = JSON.parse(content.trim());

      expect(logEntry).toHaveProperty('timestamp');
      expect(logEntry).toHaveProperty('level');
      expect(logEntry).toHaveProperty('message');
      expect(logEntry.message).toBe('Test message');
      expect(logEntry.key).toBe('value');
      expect(logEntry.number).toBe(42);
    });

    it('should handle special characters in log messages', async () => {
      const logFile = path.join(testLogDir, 'special-chars.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO,
        batchSize: 1
      });

      logger.info('Message with "quotes" and \\backslashes\\', {
        special: 'newline\nand\ttab'
      });

      logger.stop();
      await new Promise(resolve => setTimeout(resolve, 150));

      const content = fs.readFileSync(logFile, 'utf8');
      const logEntry = JSON.parse(content.trim());

      expect(logEntry.message).toContain('quotes');
      expect(logEntry.special).toContain('\n');
    });
  });

  describe('error handling', () => {
    it('should handle write errors gracefully', async () => {
      const logFile = path.join(testLogDir, 'write-error.log');
      const logger = new Logger({
        filePath: logFile,
        level: LogLevel.INFO
      });

      logger.info('Test message');
      logger.stop();

      // Try to log after stop - should not throw
      logger.info('After stop');

      expect(true).toBe(true);
    });
  });
});

import { NotificationSystem, NotificationPayload } from '../notification-system';
import { Severity, Action, NotificationConfig } from '../../types';

// Mock functions that will be used by the mocked modules
let mockHttpsRequest: jest.Mock;
let mockHttpRequest: jest.Mock;

jest.mock('https', () => ({
  request: jest.fn()
}));

jest.mock('http', () => ({
  request: jest.fn()
}));

import * as https from 'https';
import * as http from 'http';

// Get the mocked functions
mockHttpsRequest = https.request as unknown as jest.Mock;
mockHttpRequest = http.request as unknown as jest.Mock;

describe('NotificationSystem', () => {
  beforeEach(() => {
    jest.clearAllMocks();

    // Default mock implementation
    const mockResponse = {
      statusCode: 200,
      on: jest.fn((event, handler) => {
        if (event === 'data') {
          handler(Buffer.from('{"ok":true}'));
        }
        if (event === 'end') {
          handler();
        }
      })
    };

    const mockRequest: any = {
      write: jest.fn(),
      end: jest.fn(),
      on: jest.fn((event: string, handler: any): any => {
        if (event === 'error') {
          // Store error handler for later use
        }
        return mockRequest;
      })
    };

    mockHttpsRequest.mockImplementation((options: any, callback: any) => {
      if (callback) {
        setTimeout(() => callback(mockResponse as any), 10);
      }
      return mockRequest as any;
    });

    mockHttpRequest.mockImplementation((options: any, callback: any) => {
      if (callback) {
        setTimeout(() => callback(mockResponse as any), 10);
      }
      return mockRequest as any;
    });
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  const createMockConfig = (overrides?: Partial<NotificationConfig>): NotificationConfig => ({
    enabled: true,
    channels: {},
    severity_threshold: Severity.HIGH,
    ...overrides
  });

  const createMockPayload = (overrides?: Partial<NotificationPayload>): NotificationPayload => ({
    severity: Severity.HIGH,
    action: Action.BLOCK,
    userId: 'user-123',
    module: 'prompt_injection',
    fingerprint: 'fp-123',
    message: 'Security threat detected',
    timestamp: new Date().toISOString(),
    ...overrides
  });

  describe('constructor', () => {
    it('should create instance successfully', () => {
      const config = createMockConfig();
      const notifier = new NotificationSystem(config);
      expect(notifier).toBeInstanceOf(NotificationSystem);
    });

    it('should throw error if config is null', () => {
      expect(() => new NotificationSystem(null as any)).toThrow('Configuration is required');
    });

    it('should handle disabled notifications', () => {
      const config = createMockConfig({ enabled: false });
      const notifier = new NotificationSystem(config);
      expect(notifier).toBeInstanceOf(NotificationSystem);
    });
  });

  describe('notify', () => {
    it('should not send notification if notifications are disabled', async () => {
      const config = createMockConfig({ enabled: false });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(false);
      expect(result.reason).toContain('disabled');
      expect(mockHttpsRequest).not.toHaveBeenCalled();
    });

    it('should not send notification if severity below threshold', async () => {
      const config = createMockConfig({ severity_threshold: Severity.CRITICAL });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload({ severity: Severity.HIGH });

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(false);
      expect(result.reason).toContain('below threshold');
      expect(mockHttpsRequest).not.toHaveBeenCalled();
    });

    it('should not send notification if no channels configured', async () => {
      const config = createMockConfig();
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(false);
      expect(result.reason).toContain('No notification channels');
      expect(mockHttpsRequest).not.toHaveBeenCalled();
    });

    it('should send notification when severity meets threshold', async () => {
      const config = createMockConfig({
        severity_threshold: Severity.HIGH,
        channels: {
          webhook: {
            enabled: true,
            url: 'https://example.com/webhook'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload({ severity: Severity.CRITICAL });

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(true);
      expect(result.channels).toContain('webhook');
      expect(mockHttpsRequest).toHaveBeenCalled();
    });
  });

  describe('webhook notifications', () => {
    it('should send webhook notification', async () => {
      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'https://example.com/webhook'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(true);
      expect(result.channels).toContain('webhook');
      expect(mockHttpsRequest).toHaveBeenCalled();

      const callArgs = mockHttpsRequest.mock.calls[0];
      const options = callArgs[0] as any;
      expect(options.method).toBe('POST');
      expect(options.headers['Content-Type']).toBe('application/json');
    });

    it('should handle webhook errors gracefully', async () => {
      // Mock error response
      const mockErrorRequest: any = {
        write: jest.fn(),
        end: jest.fn(),
        on: jest.fn((event: string, handler: any): any => {
          if (event === 'error') {
            setTimeout(() => handler(new Error('Network error')), 10);
          }
          return mockErrorRequest;
        })
      };

      mockHttpsRequest.mockImplementation(() => mockErrorRequest as any);

      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'https://example.com/webhook'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(false);
      expect(result.errors).toBeDefined();
      expect(result.errors!.webhook).toContain('Network error');
    });

    it('should handle HTTP webhook URLs', async () => {
      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'http://example.com/webhook'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      await notifier.notify(payload);

      expect(mockHttpRequest).toHaveBeenCalled();
    });
  });

  describe('Slack notifications', () => {
    it('should send Slack notification', async () => {
      const config = createMockConfig({
        channels: {
          slack: {
            enabled: true,
            webhook_url: 'https://hooks.slack.com/services/XXX/YYY/ZZZ'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(true);
      expect(result.channels).toContain('slack');
      expect(mockHttpsRequest).toHaveBeenCalled();

      // Check Slack-specific formatting
      const callArgs = mockHttpsRequest.mock.calls[0];
      const requestMock = mockHttpsRequest.mock.results[0].value;
      expect(requestMock.write).toHaveBeenCalled();

      const writtenData = requestMock.write.mock.calls[0][0];
      const payload_data = JSON.parse(writtenData);
      expect(payload_data).toHaveProperty('text');
    });

    it('should format Slack message with severity colors', async () => {
      const config = createMockConfig({
        channels: {
          slack: {
            enabled: true,
            webhook_url: 'https://hooks.slack.com/services/XXX/YYY/ZZZ'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload({ severity: Severity.CRITICAL });

      await notifier.notify(payload);

      const requestMock = mockHttpsRequest.mock.results[0].value;
      const writtenData = requestMock.write.mock.calls[0][0];
      const slackPayload = JSON.parse(writtenData);

      expect(slackPayload.attachments[0].color).toBe('danger');
      expect(slackPayload.attachments[0].fields.some((f: any) => f.value === 'CRITICAL')).toBe(true);
    });
  });

  describe('Discord notifications', () => {
    it('should send Discord notification', async () => {
      const config = createMockConfig({
        channels: {
          discord: {
            enabled: true,
            webhook_url: 'https://discord.com/api/webhooks/XXX/YYY'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(true);
      expect(result.channels).toContain('discord');
      expect(mockHttpsRequest).toHaveBeenCalled();

      // Check Discord-specific formatting
      const requestMock = mockHttpsRequest.mock.results[0].value;
      const writtenData = requestMock.write.mock.calls[0][0];
      const discordPayload = JSON.parse(writtenData);
      expect(discordPayload).toHaveProperty('content');
    });

    it('should format Discord embeds for high severity', async () => {
      const config = createMockConfig({
        channels: {
          discord: {
            enabled: true,
            webhook_url: 'https://discord.com/api/webhooks/XXX/YYY'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload({ severity: Severity.CRITICAL });

      await notifier.notify(payload);

      const requestMock = mockHttpsRequest.mock.results[0].value;
      const writtenData = requestMock.write.mock.calls[0][0];
      const discordPayload = JSON.parse(writtenData);

      expect(discordPayload.embeds[0].title).toContain('CRITICAL');
      expect(discordPayload.embeds[0].color).toBe(0xff0000); // Red
    });
  });

  describe('multiple channels', () => {
    it('should send to all enabled channels', async () => {
      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'https://example.com/webhook'
          },
          slack: {
            enabled: true,
            webhook_url: 'https://hooks.slack.com/services/XXX/YYY/ZZZ'
          },
          discord: {
            enabled: true,
            webhook_url: 'https://discord.com/api/webhooks/XXX/YYY'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(true);
      expect(result.channels).toHaveLength(3);
      expect(result.channels).toContain('webhook');
      expect(result.channels).toContain('slack');
      expect(result.channels).toContain('discord');
      expect(mockHttpsRequest).toHaveBeenCalledTimes(3);
    });

    it('should continue sending even if one channel fails', async () => {
      let callCount = 0;
      mockHttpsRequest.mockImplementation(() => {
        callCount++;
        if (callCount === 1) {
          // First call fails
          const mockErrorRequest: any = {
            write: jest.fn(),
            end: jest.fn(),
            on: jest.fn((event: string, handler: any): any => {
              if (event === 'error') {
                setTimeout(() => handler(new Error('Failed')), 10);
              }
              return mockErrorRequest;
            })
          };
          return mockErrorRequest as any;
        } else {
          // Subsequent calls succeed
          const mockResponse = {
            statusCode: 200,
            on: jest.fn((event, handler) => {
              if (event === 'data') handler(Buffer.from('{"ok":true}'));
              if (event === 'end') handler();
            })
          };
          const mockRequest = {
            write: jest.fn(),
            end: jest.fn(),
            on: jest.fn()
          };
          setTimeout(() => {
            const callback = mockHttpsRequest.mock.calls[callCount - 1][1];
            if (callback) callback(mockResponse as any);
          }, 10);
          return mockRequest as any;
        }
      });

      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'https://example.com/webhook'
          },
          slack: {
            enabled: true,
            webhook_url: 'https://hooks.slack.com/services/XXX/YYY/ZZZ'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      // Should still succeed with slack even though webhook failed
      expect(result.channels).toContain('slack');
      expect(result.errors).toBeDefined();
      expect(result.errors!.webhook).toBeDefined();
    });
  });

  describe('error handling', () => {
    it('should handle invalid webhook URL', async () => {
      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'invalid-url'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      const result = await notifier.notify(payload);

      expect(result.sent).toBe(false);
      expect(result.errors).toBeDefined();
    });

    it('should handle network timeouts gracefully', async () => {
      // This is a simplified test - real timeout handling would be more complex
      const config = createMockConfig({
        channels: {
          webhook: {
            enabled: true,
            url: 'https://example.com/webhook'
          }
        }
      });
      const notifier = new NotificationSystem(config);
      const payload = createMockPayload();

      // Mock will respond quickly, so this just tests the happy path
      const result = await notifier.notify(payload);
      expect(result).toBeDefined();
    });
  });
});

