        {
          userId: 'user-123',
          sessionId: 'session-123'
        }
      );

      expect(result.recommendations).toBeDefined();
      expect(result.recommendations.length).toBeGreaterThan(0);

      await engine.stop();
    });
  });
});

import { SeverityScorer } from '../severity-scorer';
import { Severity, Finding, SecurityPattern } from '../../types';

describe('SeverityScorer', () => {
  const createMockPattern = (severity: Severity): SecurityPattern => ({
    id: 'test-pattern',
    category: 'test',
    pattern: /test/,
    severity,
    language: 'en',
    description: 'Test pattern',
    examples: [],
    falsePositiveRisk: 'low',
    enabled: true,
    tags: []
  });

  const createMockFinding = (module: string, severity: Severity): Finding => ({
    module,
    pattern: createMockPattern(severity),
    matchedText: 'test',
    severity
  });

  describe('constructor', () => {
    it('should create instance successfully', () => {
      const scorer = new SeverityScorer();
      expect(scorer).toBeInstanceOf(SeverityScorer);
    });
  });

  describe('calculateSeverity', () => {
    it('should return SAFE for empty findings', () => {
      const scorer = new SeverityScorer();
      const result = scorer.calculateSeverity([]);

      expect(result.severity).toBe(Severity.SAFE);
      expect(result.reasoning).toContain('No security findings detected');
      expect(result.findingCount).toBe(0);
      expect(result.modulesConcerned).toEqual([]);
    });

    it('should return highest severity when multiple findings exist', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = [
        createMockFinding('prompt_injection', Severity.LOW),
        createMockFinding('command_validator', Severity.CRITICAL),
        createMockFinding('url_validator', Severity.MEDIUM)
      ];

      const result = scorer.calculateSeverity(findings);

      expect(result.severity).toBe(Severity.CRITICAL);
      expect(result.reasoning).toContain('CRITICAL');
      expect(result.findingCount).toBe(3);
      expect(result.modulesConcerned).toContain('command_validator');
    });

    it('should handle single finding', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = [
        createMockFinding('prompt_injection', Severity.HIGH)
      ];

      const result = scorer.calculateSeverity(findings);

      expect(result.severity).toBe(Severity.HIGH);
      expect(result.findingCount).toBe(1);
      expect(result.modulesConcerned).toEqual(['prompt_injection']);
    });

    it('should identify all concerned modules', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = [
        createMockFinding('prompt_injection', Severity.LOW),
        createMockFinding('command_validator', Severity.MEDIUM),
        createMockFinding('url_validator', Severity.LOW),
        createMockFinding('command_validator', Severity.HIGH) // duplicate module
      ];

      const result = scorer.calculateSeverity(findings);

      expect(result.modulesConcerned).toHaveLength(3);
      expect(result.modulesConcerned).toContain('prompt_injection');
      expect(result.modulesConcerned).toContain('command_validator');
      expect(result.modulesConcerned).toContain('url_validator');
    });

    it('should correctly order severity levels (CRITICAL > HIGH > MEDIUM > LOW > SAFE)', () => {
      const scorer = new SeverityScorer();

      const testCases = [
        { findings: [Severity.LOW, Severity.MEDIUM], expected: Severity.MEDIUM },
        { findings: [Severity.MEDIUM, Severity.HIGH], expected: Severity.HIGH },
        { findings: [Severity.HIGH, Severity.CRITICAL], expected: Severity.CRITICAL },
        { findings: [Severity.LOW, Severity.HIGH, Severity.MEDIUM], expected: Severity.HIGH }
      ];

      testCases.forEach(({ findings, expected }) => {
        const mockFindings = findings.map((sev, idx) =>
          createMockFinding(`module_${idx}`, sev)
        );
        const result = scorer.calculateSeverity(mockFindings);
        expect(result.severity).toBe(expected);
      });
    });

    it('should provide detailed reasoning for multiple modules', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = [
        createMockFinding('prompt_injection', Severity.HIGH),
        createMockFinding('command_validator', Severity.MEDIUM)
      ];

      const result = scorer.calculateSeverity(findings);

      expect(result.reasoning).toContain('HIGH');
      expect(result.reasoning).toContain('2 findings');
      expect(result.reasoning).toContain('2 modules');
    });

    it('should handle all severity levels correctly', () => {
      const scorer = new SeverityScorer();
      const severities = [Severity.SAFE, Severity.LOW, Severity.MEDIUM, Severity.HIGH, Severity.CRITICAL];

      severities.forEach(severity => {
        const findings: Finding[] = [createMockFinding('test_module', severity)];
        const result = scorer.calculateSeverity(findings);
        expect(result.severity).toBe(severity);
      });
    });

    it('should include severity breakdown in metadata', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = [
        createMockFinding('module1', Severity.LOW),
        createMockFinding('module2', Severity.LOW),
        createMockFinding('module3', Severity.HIGH),
        createMockFinding('module4', Severity.CRITICAL)
      ];

      const result = scorer.calculateSeverity(findings);

      expect(result.severityBreakdown).toBeDefined();
      expect(result.severityBreakdown![Severity.LOW]).toBe(2);
      expect(result.severityBreakdown![Severity.HIGH]).toBe(1);
      expect(result.severityBreakdown![Severity.CRITICAL]).toBe(1);
    });

    it('should throw error for null findings', () => {
      const scorer = new SeverityScorer();
      expect(() => scorer.calculateSeverity(null as any)).toThrow('Findings must be an array');
    });

    it('should throw error for undefined findings', () => {
      const scorer = new SeverityScorer();
      expect(() => scorer.calculateSeverity(undefined as any)).toThrow('Findings must be an array');
    });

    it('should throw error for non-array findings', () => {
      const scorer = new SeverityScorer();
      expect(() => scorer.calculateSeverity('invalid' as any)).toThrow('Findings must be an array');
    });
  });

  describe('edge cases', () => {
    it('should handle findings with metadata', () => {
      const scorer = new SeverityScorer();
      const finding: Finding = {
        ...createMockFinding('test_module', Severity.MEDIUM),
        metadata: { customField: 'value', position: 10 }
      };

      const result = scorer.calculateSeverity([finding]);

      expect(result.severity).toBe(Severity.MEDIUM);
      expect(result.findingCount).toBe(1);
    });

    it('should handle multiple findings from same module', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = [
        createMockFinding('prompt_injection', Severity.LOW),
        createMockFinding('prompt_injection', Severity.MEDIUM),
        createMockFinding('prompt_injection', Severity.HIGH)
      ];

      const result = scorer.calculateSeverity(findings);

      expect(result.severity).toBe(Severity.HIGH);
      expect(result.findingCount).toBe(3);
      expect(result.modulesConcerned).toEqual(['prompt_injection']);
    });

    it('should handle large number of findings', () => {
      const scorer = new SeverityScorer();
      const findings: Finding[] = Array(1000).fill(null).map((_, idx) =>
        createMockFinding(`module_${idx % 6}`, Severity.LOW)
      );

      const result = scorer.calculateSeverity(findings);

      expect(result.severity).toBe(Severity.LOW);
      expect(result.findingCount).toBe(1000);
      expect(result.modulesConcerned.length).toBeLessThanOrEqual(6);
    });
  });

  describe('severity ordering', () => {
    it('should use correct severity weight hierarchy', () => {
      const scorer = new SeverityScorer();

      // Test all combinations to ensure proper ordering
      const allSeverities = [Severity.SAFE, Severity.LOW, Severity.MEDIUM, Severity.HIGH, Severity.CRITICAL];

      for (let i = 0; i < allSeverities.length; i++) {
        for (let j = i + 1; j < allSeverities.length; j++) {
          const findings = [
            createMockFinding('module1', allSeverities[i]),
            createMockFinding('module2', allSeverities[j])
          ];
          const result = scorer.calculateSeverity(findings);

          // Higher index should always win
          expect(result.severity).toBe(allSeverities[j]);
        }
      }
    });
  });
});

import { Severity, Action, SecurityConfig } from '../types';
import { DatabaseManager } from './database-manager';

/**
 * Result of action determination
 */
export interface ActionResult {
  action: Action;
  reasoning: string;
  bypassReason?: 'owner' | 'allowlisted' | 'trusted';
  upgraded?: boolean;
}

/**
 * ActionEngine determines what action to take based on severity level,
 * user configuration, and user reputation.
 *
 * Decision hierarchy:
 * 1. Blocklisted users - always BLOCK
 * 2. Owner users - always ALLOW (unless CRITICAL)
 * 3. Allowlisted users - ALLOW for non-CRITICAL
 * 4. Low trust score - upgrade action by one level
 * 5. Default action mapping from config
 *
 * @example
 * ```typescript
 * const engine = new ActionEngine(config, dbManager);
 * const result = await engine.determineAction(Severity.HIGH, 'user-123');
 * console.log(result.action); // Action.BLOCK
 * console.log(result.reasoning); // "Severity HIGH maps to BLOCK action"
 * ```
 */
export class ActionEngine {
  private readonly config: SecurityConfig;
  private readonly dbManager: DatabaseManager;
  private readonly actionHierarchy: Action[] = [
    Action.ALLOW,
    Action.LOG,
    Action.WARN,
    Action.BLOCK,
    Action.BLOCK_NOTIFY
  ];

  /**
   * Default action mappings if not specified in config
   */
  private readonly defaultActionMap: Record<Severity, Action> = {
    [Severity.SAFE]: Action.ALLOW,
    [Severity.LOW]: Action.LOG,
    [Severity.MEDIUM]: Action.WARN,
    [Severity.HIGH]: Action.BLOCK,
    [Severity.CRITICAL]: Action.BLOCK_NOTIFY
  };

  /**
   * Creates a new ActionEngine instance
   *
   * @param config - Security configuration
   * @param dbManager - Database manager for reputation lookups
   * @throws Error if config or dbManager is missing
   */
  constructor(config: SecurityConfig, dbManager?: DatabaseManager | null) {
    if (!config) {
      throw new Error('Configuration is required');
    }
    this.config = config;
    this.dbManager = dbManager!;
  }

  /**
   * Determine the appropriate action for a given severity and user
   *
   * @param severity - The severity level from SeverityScorer
   * @param userId - The user ID to check reputation
   * @returns ActionResult with action and reasoning
   * @throws Error if severity is invalid or userId is missing
   */
  async determineAction(severity: Severity, userId: string): Promise<ActionResult> {
    // Validate inputs
    if (!Object.values(Severity).includes(severity)) {
      throw new Error(`Invalid severity: ${severity}`);
    }

    if (!userId || userId.trim().length === 0) {
      throw new Error('User ID is required');
    }

    // Get base action from config or defaults
    const baseAction = this.config.actions?.[severity] ?? this.defaultActionMap[severity];

    try {
      // Check if user is blocklisted
      const reputation = await this.getUserReputation(userId);
      if (reputation?.is_blocklisted === 1) {
        return {
          action: Action.BLOCK,
          reasoning: `User is blocklisted. All requests blocked regardless of severity.`
        };
      }

      // Check if user is an owner
      if (this.config.owner_ids.includes(userId)) {
        return {
          action: Action.ALLOW,
          reasoning: `User is an owner. Request allowed.`,
          bypassReason: 'owner'
        };
      }

      // Check if user is allowlisted (but not for CRITICAL severity)
      if (reputation?.is_allowlisted === 1 && severity !== Severity.CRITICAL) {
        return {
          action: Action.ALLOW,
          reasoning: `User is allowlisted. Severity ${severity} allowed.`,
          bypassReason: 'allowlisted'
        };
      }

      // Check trust score and potentially upgrade action
      if (reputation && reputation.trust_score < 20) {
        const upgradedAction = this.upgradeAction(baseAction);
        if (upgradedAction !== baseAction) {
          return {
            action: upgradedAction,
            reasoning: `Severity ${severity} with low trust score (${reputation.trust_score}). Action upgraded from ${baseAction} to ${upgradedAction}.`,
            upgraded: true
          };
        }
      }

      // Return base action
      return {
        action: baseAction,
        reasoning: `Severity ${severity} maps to ${baseAction} action.`
      };
    } catch (error) {
      // If database lookup fails, use base action
      // This ensures the system is resilient to database issues
      return {
        action: baseAction,
        reasoning: `Severity ${severity} maps to ${baseAction} action.`
      };
    }
  }

  /**
   * Get user reputation from database
   * @private
   */
  private async getUserReputation(userId: string) {
    if (!this.dbManager) return null; // NO_DB mode
    try {
      return this.dbManager.getUserReputation(userId);
    } catch (error) {
      // Return null if database error - system will use defaults
      return null;
    }
  }

  /**
   * Upgrade action to next level in hierarchy
   * @private
   */
  private upgradeAction(action: Action): Action {
    const currentIndex = this.actionHierarchy.indexOf(action);

    // If already at highest level or not found, return as-is
    if (currentIndex === -1 || currentIndex >= this.actionHierarchy.length - 1) {
      return action;
    }

    // Return next level action
    return this.actionHierarchy[currentIndex + 1];
  }
}

/**
 * Options for configuring the AsyncQueue
 */
export interface AsyncQueueOptions {
  /**
   * Number of tasks to batch together before processing
   * @default 50
   */
  batchSize?: number;

  /**
   * Interval in milliseconds to flush pending tasks
   * @default 100
   */
  flushInterval?: number;

  /**
   * Maximum number of tasks to keep in queue
   * When exceeded, oldest tasks are dropped
   * @default 10000
   */
  maxQueueSize?: number;

  /**
   * Callback function to process a batch of tasks
   * @param tasks - Array of tasks to process
   */
  onBatch: (tasks: any[]) => Promise<void>;
}

/**
 * AsyncQueue provides non-blocking batch processing of tasks
 *
 * Features:
 * - Automatic batching when batch size is reached
 * - Periodic flushing based on time interval
 * - Queue overflow protection (drops oldest tasks)
 * - Error handling for batch processing failures
 * - Manual flush support
 *
 * @example
 * ```typescript
 * const queue = new AsyncQueue({
 *   batchSize: 50,
 *   flushInterval: 100,
 *   onBatch: async (tasks) => {
 *     await database.insertMany(tasks);
 *   }
 * });
 *
 * queue.enqueue({ type: 'event', data: {...} });
 * await queue.flush(); // Manual flush
 * queue.stop(); // Cleanup
 * ```
 */
export class AsyncQueue {
  private queue: any[] = [];
  private readonly batchSize: number;
  private readonly flushInterval: number;
  private readonly maxQueueSize: number;
  private readonly onBatch: (tasks: any[]) => Promise<void>;
  private timer: NodeJS.Timeout | null = null;
  private isProcessing = false;

  /**
   * Creates a new AsyncQueue instance
   * @param options - Configuration options
   * @throws Error if options are invalid
   */
  constructor(options: AsyncQueueOptions) {
    // Validate required options
    if (!options.onBatch) {
      throw new Error('onBatch callback is required');
    }

    if (typeof options.onBatch !== 'function') {
      throw new Error('onBatch must be a function');
    }

    // Set defaults
    this.batchSize = options.batchSize ?? 50;
    this.flushInterval = options.flushInterval ?? 100;
    this.maxQueueSize = options.maxQueueSize ?? 10000;
    this.onBatch = options.onBatch;

    // Validate options
    if (this.batchSize <= 0) {
      throw new Error('batchSize must be greater than 0');
    }

    if (this.flushInterval <= 0) {
      throw new Error('flushInterval must be greater than 0');
    }

    if (this.maxQueueSize <= 0) {
      throw new Error('maxQueueSize must be greater than 0');
    }

    // Start the periodic flush timer
    this.startTimer();
  }

  /**
   * Add a task to the queue
   * Automatically processes batch when batch size is reached
   * @param task - Task to enqueue
   */
  enqueue(task: any): void {
    // Add task to queue
    this.queue.push(task);

    // Handle queue overflow - drop oldest tasks
    while (this.queue.length > this.maxQueueSize) {
      this.queue.shift();
    }

    // Process batch if batch size is reached
    if (this.queue.length >= this.batchSize) {
      this.processBatch();
    }
  }

  /**
   * Returns the current number of tasks in the queue
   * @returns Queue size
   */
  size(): number {
    return this.queue.length;
  }

  /**
   * Process all remaining tasks in the queue
   * Waits for processing to complete
   * @returns Promise that resolves when all tasks are processed
   */
  async flush(): Promise<void> {
    if (this.queue.length === 0) {
      return;
    }

    const batch = this.queue.splice(0, this.queue.length);
    await this.onBatch(batch);
  }

  /**
   * Stop the periodic flush timer and cleanup
   * Does not flush remaining tasks - call flush() first if needed
   */
  stop(): void {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  /**
   * Start the periodic flush timer
   * @private
   */
  private startTimer(): void {
    this.timer = setInterval(() => {
      if (this.queue.length > 0 && !this.isProcessing) {
        this.processBatch();
      }
    }, this.flushInterval) as any; // Cast to any for compatibility with both Node.js and fake timers
  }

  /**
   * Process a batch of tasks asynchronously
   * Handles errors without throwing
   * @private
   */
  private processBatch(): void {
    // Prevent concurrent batch processing
    if (this.isProcessing || this.queue.length === 0) {
      return;
    }

    this.isProcessing = true;

    // Extract batch
    const batchCount = Math.min(this.batchSize, this.queue.length);
    const batch = this.queue.splice(0, batchCount);

    // Process asynchronously
    this.onBatch(batch)
      .catch((error) => {
        console.error('Error processing batch:', error);
      })
      .finally(() => {
        this.isProcessing = false;
      });
  }
}

import * as fs from 'fs';
import * as yaml from 'yaml';
import { SecurityConfig, Severity, Action } from '../types';

/**
 * ConfigManager handles loading and validating security configuration from YAML files.
 * Supports deep merging of user configs with defaults and comprehensive validation.
 */
export class ConfigManager {
  /**
   * Returns the default security configuration.
   * This is used when no config file exists or as a base for merging user configs.
   */
  static getDefaultConfig(): SecurityConfig {
    return {
      enabled: true,
      sensitivity: 'medium',
      owner_ids: [],
      modules: {
        prompt_injection: { enabled: true },
        command_validator: { enabled: true },
        url_validator: { enabled: true },
        path_validator: { enabled: true },
        secret_detector: { enabled: true },
        content_scanner: { enabled: true },
        injection_validator: { enabled: true },
        exfiltration_detector: { enabled: true },
        code_execution_detector: { enabled: true },
        serialization_detector: { enabled: true }
      },
      actions: {
        [Severity.SAFE]: Action.ALLOW,
        [Severity.LOW]: Action.LOG,
        [Severity.MEDIUM]: Action.WARN,
        [Severity.HIGH]: Action.BLOCK,
        [Severity.CRITICAL]: Action.BLOCK_NOTIFY
      },
      rate_limit: {
        enabled: true,
        max_requests_per_minute: 30,
        lockout_threshold: 5
      },
      notifications: {
        enabled: false,
        channels: {},
        severity_threshold: Severity.HIGH
      },
      logging: {
        enabled: true,
        level: 'info',
        file: '~/.openclaw/logs/security-events.log',
        rotation: 'daily',
        retention_days: 90
      },
      database: {
        path: '.openclaw-sec.db',
        analytics_enabled: true,
        retention_days: 365
      }
    };
  }

  /**
   * Loads configuration from a YAML file, merging with defaults.
   * Returns default config if file doesn't exist.
   *
   * @param configPath - Path to the YAML config file
   * @returns Promise<SecurityConfig> - The merged and validated configuration
   * @throws Error if YAML is invalid or config validation fails
   */
  static async load(configPath: string): Promise<SecurityConfig> {
    // Return defaults if file doesn't exist
    if (!fs.existsSync(configPath)) {
      return this.getDefaultConfig();
    }

    try {
      // Read and parse YAML file
      const fileContent = fs.readFileSync(configPath, 'utf8');
      const parsed = yaml.parse(fileContent);

      if (!parsed) {
        throw new Error(`Invalid YAML in config file: ${configPath}`);
      }

      // Extract openclaw_security section
      const userConfig = parsed.openclaw_security || {};
      const defaultConfig = this.getDefaultConfig();

      // Deep merge user config with defaults
      const merged = this.deepMerge(defaultConfig, userConfig);

      // Validate the merged configuration
      this.validateConfig(merged);

      return merged;
    } catch (error) {
      if (error instanceof Error) {
        throw new Error(`Failed to load config from ${configPath}: ${error.message}`);
      }
      throw error;
    }
  }

  /**
   * Deep merges two objects, with source values overriding target values.
   * Arrays are replaced entirely, not merged.
   *
   * @param target - The base object
   * @param source - The object to merge in
   * @returns The merged object
   */
  static deepMerge(target: any, source: any): any {
    const output = { ...target };

    if (this.isObject(target) && this.isObject(source)) {
      Object.keys(source).forEach(key => {
        if (this.isObject(source[key]) && !Array.isArray(source[key])) {
          if (!(key in target)) {
            output[key] = source[key];
          } else {
            output[key] = this.deepMerge(target[key], source[key]);
          }
        } else {
          // Replace arrays and primitive values entirely
          output[key] = source[key];
        }
      });
    }

    return output;
  }

  /**
   * Checks if a value is a plain object (not null, array, or other type).
   */
  private static isObject(item: any): boolean {
    return item && typeof item === 'object' && !Array.isArray(item);
  }

  /**
   * Validates a security configuration.
   * Checks sensitivity levels and actions for correctness.
   *
   * @param config - The config to validate
   * @throws Error if validation fails
   */
  static validateConfig(config: SecurityConfig): void {
    // Validate sensitivity level
    const validSensitivities: Array<SecurityConfig['sensitivity']> = [
      'paranoid',
      'strict',
      'medium',
      'permissive'
    ];

    if (!validSensitivities.includes(config.sensitivity)) {
      throw new Error(`Invalid sensitivity level: ${config.sensitivity}. Must be one of: ${validSensitivities.join(', ')}`);
    }

    // Validate actions
    const validActions = Object.values(Action);

    if (config.actions) {
      Object.entries(config.actions).forEach(([severity, action]) => {
        if (!validActions.includes(action)) {
          throw new Error(`Invalid action for ${severity}: ${action}. Must be one of: ${validActions.join(', ')}`);
        }
      });
    }

    // Validate module-specific sensitivity levels if present
    if (config.modules) {
      Object.entries(config.modules).forEach(([moduleName, moduleConfig]) => {
        if (moduleConfig.sensitivity && !validSensitivities.includes(moduleConfig.sensitivity)) {
          throw new Error(`Invalid sensitivity level for module ${moduleName}: ${moduleConfig.sensitivity}`);
        }
      });
    }
  }
}

import Database from 'better-sqlite3';
import { Severity, Action } from '../types';

export class DatabaseError extends Error {
  constructor(message: string, public readonly cause?: unknown) {
    super(message);
    this.name = 'DatabaseError';
    if (cause instanceof Error) {
      this.stack = `${this.stack}\nCaused by: ${cause.stack}`;
    }
  }
}

export interface SecurityEvent {
  id?: number;
  timestamp?: string;
  event_type: string;
  severity: Severity;
  action_taken: Action;
  user_id: string;
  session_id: string;
  input_text: string;
  patterns_matched: string;
  fingerprint: string;
  module: string;
  metadata: string;
}

export interface RateLimit {
  user_id: string;
  request_count: number;
  window_start: string;
  lockout_until?: string;
  failed_attempts: number;
}

export interface UserReputation {
  user_id: string;
  trust_score: number;
  total_requests: number;
  blocked_attempts: number;
  last_violation?: string;
  is_allowlisted: number;
  is_blocklisted: number;
  notes?: string;
}

export interface AttackPattern {
  id?: number;
  pattern: string;
  category: string;
  severity: Severity;
  language: string;
  times_matched: number;
  last_matched?: string;
  is_custom: number;
  enabled: number;
}

export interface NotificationLog {
  id?: number;
  timestamp?: string;
  channel: string;
  severity: Severity;
  message: string;
  delivery_status: string;
  event_id: number;
}

export class DatabaseManager {
  private db: Database.Database;
  private isClosed: boolean = false;

  constructor(dbPath: string) {
    try {
      this.db = new Database(dbPath);
      // Enable foreign key constraints before initializing schema
      this.db.pragma('foreign_keys = ON');
      this.initializeSchema();
    } catch (error) {
      throw new DatabaseError('Failed to initialize database', error);
    }
  }

  private ensureNotClosed(): void {
    if (this.isClosed) {
      throw new DatabaseError('Database connection is closed');
    }
  }

  private validateSeverity(severity: Severity): void {
    const validSeverities = Object.values(Severity);
    if (!validSeverities.includes(severity)) {
      throw new DatabaseError(`Invalid severity: ${severity}. Must be one of: ${validSeverities.join(', ')}`);
    }
  }

  private validateAction(action: Action): void {
    const validActions = Object.values(Action);
    if (!validActions.includes(action)) {
      throw new DatabaseError(`Invalid action: ${action}. Must be one of: ${validActions.join(', ')}`);
    }
  }

  private validatePositiveInteger(value: number, fieldName: string): void {
    if (!Number.isInteger(value) || value < 0) {
      throw new DatabaseError(`${fieldName} must be a positive integer, got: ${value}`);
    }
  }

  private validateRequiredString(value: string, fieldName: string): void {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new DatabaseError(`${fieldName} is required and must be a non-empty string`);
    }
  }

  private initializeSchema(): void {
    // Security Events Table
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS security_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        event_type TEXT NOT NULL,
        severity TEXT NOT NULL,
        action_taken TEXT NOT NULL,
        user_id TEXT NOT NULL,
        session_id TEXT NOT NULL,
        input_text TEXT NOT NULL,
        patterns_matched TEXT NOT NULL,
        fingerprint TEXT NOT NULL,
        module TEXT NOT NULL,
        metadata TEXT DEFAULT '{}'
      );
    `);

    // Create indexes for security_events
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_events_timestamp ON security_events(timestamp);
      CREATE INDEX IF NOT EXISTS idx_events_user_id ON security_events(user_id);
      CREATE INDEX IF NOT EXISTS idx_events_severity ON security_events(severity);
      CREATE INDEX IF NOT EXISTS idx_events_fingerprint ON security_events(fingerprint);
    `);

    // Rate Limits Table
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS rate_limits (
        user_id TEXT PRIMARY KEY,
        request_count INTEGER DEFAULT 0,
        window_start DATETIME NOT NULL,
        lockout_until DATETIME,
        failed_attempts INTEGER DEFAULT 0
      );
    `);

    // Create indexes for rate_limits
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_rate_limits_window_start ON rate_limits(window_start);
    `);

    // User Reputation Table
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS user_reputation (
        user_id TEXT PRIMARY KEY,
        trust_score REAL DEFAULT 100.0,
        total_requests INTEGER DEFAULT 0,
        blocked_attempts INTEGER DEFAULT 0,
        last_violation DATETIME,
        is_allowlisted INTEGER DEFAULT 0,
        is_blocklisted INTEGER DEFAULT 0,
        notes TEXT
      );
    `);

    // Create indexes for user_reputation
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_reputation_trust_score ON user_reputation(trust_score);
    `);

    // Attack Patterns Table
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS attack_patterns (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        pattern TEXT NOT NULL UNIQUE,
        category TEXT NOT NULL,
        severity TEXT NOT NULL,
        language TEXT NOT NULL,
        times_matched INTEGER DEFAULT 0,
        last_matched DATETIME,
        is_custom INTEGER DEFAULT 0,
        enabled INTEGER DEFAULT 1
      );
    `);

    // Create indexes for attack_patterns
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_patterns_pattern ON attack_patterns(pattern);
      CREATE INDEX IF NOT EXISTS idx_patterns_category ON attack_patterns(category);
      CREATE INDEX IF NOT EXISTS idx_patterns_severity ON attack_patterns(severity);
    `);

    // Notifications Log Table
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS notifications_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
        channel TEXT NOT NULL,
        severity TEXT NOT NULL,
        message TEXT NOT NULL,
        delivery_status TEXT NOT NULL,
        event_id INTEGER NOT NULL,
        FOREIGN KEY (event_id) REFERENCES security_events(id)
      );
    `);

    // Create indexes for notifications_log
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_notifications_event_id ON notifications_log(event_id);
      CREATE INDEX IF NOT EXISTS idx_notifications_timestamp ON notifications_log(timestamp);
      CREATE INDEX IF NOT EXISTS idx_notifications_delivery_status ON notifications_log(delivery_status);
    `);
  }

  public getTables(): string[] {
    this.ensureNotClosed();
    try {
      const stmt = this.db.prepare(`
        SELECT name FROM sqlite_master
        WHERE type='table' AND name NOT LIKE 'sqlite_%'
        ORDER BY name
      `);
      const results = stmt.all() as Array<{ name: string }>;
      return results.map(row => row.name);
    } catch (error) {
      throw new DatabaseError('Failed to get tables', error);
    }
  }

  // Security Events Methods
  public insertEvent(event: SecurityEvent): number {
    this.ensureNotClosed();

    // Validate required fields
    this.validateRequiredString(event.event_type, 'event_type');
    this.validateSeverity(event.severity);
    this.validateAction(event.action_taken);
    this.validateRequiredString(event.user_id, 'user_id');
    this.validateRequiredString(event.session_id, 'session_id');
    this.validateRequiredString(event.input_text, 'input_text');
    this.validateRequiredString(event.patterns_matched, 'patterns_matched');
    this.validateRequiredString(event.fingerprint, 'fingerprint');
    this.validateRequiredString(event.module, 'module');
    this.validateRequiredString(event.metadata, 'metadata');

    try {
      const stmt = this.db.prepare(`
        INSERT INTO security_events (
          event_type, severity, action_taken, user_id, session_id,
          input_text, patterns_matched, fingerprint, module, metadata
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `);

      const result = stmt.run(
        event.event_type,
        event.severity,
        event.action_taken,
        event.user_id,
        event.session_id,
        event.input_text,
        event.patterns_matched,
        event.fingerprint,
        event.module,
        event.metadata
      );

      return result.lastInsertRowid as number;
    } catch (error) {
      throw new DatabaseError('Failed to insert security event', error);
    }
  }

  public getEventById(id: number): SecurityEvent | undefined {
    this.ensureNotClosed();
    this.validatePositiveInteger(id, 'id');

    try {
      const stmt = this.db.prepare('SELECT * FROM security_events WHERE id = ?');
      return stmt.get(id) as SecurityEvent | undefined;
    } catch (error) {
      throw new DatabaseError(`Failed to get event by id ${id}`, error);
    }
  }

  public getEventsByUserId(userId: string, limit: number = 100): SecurityEvent[] {
    this.ensureNotClosed();
    this.validateRequiredString(userId, 'userId');
    this.validatePositiveInteger(limit, 'limit');

    try {
      const stmt = this.db.prepare(`
        SELECT * FROM security_events
        WHERE user_id = ?
        ORDER BY timestamp DESC
        LIMIT ?
      `);
      return stmt.all(userId, limit) as SecurityEvent[];
    } catch (error) {
      throw new DatabaseError(`Failed to get events for user ${userId}`, error);
    }
  }

  public getEventsBySeverity(severity: Severity, limit: number = 100): SecurityEvent[] {
    this.ensureNotClosed();
    this.validateSeverity(severity);
    this.validatePositiveInteger(limit, 'limit');

    try {
      const stmt = this.db.prepare(`
        SELECT * FROM security_events
        WHERE severity = ?
        ORDER BY timestamp DESC
        LIMIT ?
      `);
      return stmt.all(severity, limit) as SecurityEvent[];
    } catch (error) {
      throw new DatabaseError(`Failed to get events by severity ${severity}`, error);
    }
  }

  // Rate Limits Methods
  public upsertRateLimit(rateLimit: RateLimit): void {
    this.ensureNotClosed();
    this.validateRequiredString(rateLimit.user_id, 'user_id');
    this.validatePositiveInteger(rateLimit.request_count, 'request_count');
    this.validateRequiredString(rateLimit.window_start, 'window_start');
    this.validatePositiveInteger(rateLimit.failed_attempts, 'failed_attempts');

    try {
      const stmt = this.db.prepare(`
        INSERT INTO rate_limits (user_id, request_count, window_start, lockout_until, failed_attempts)
        VALUES (?, ?, ?, ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET
          request_count = excluded.request_count,
          window_start = excluded.window_start,
          lockout_until = excluded.lockout_until,
          failed_attempts = excluded.failed_attempts
      `);

      stmt.run(
        rateLimit.user_id,
        rateLimit.request_count,
        rateLimit.window_start,
        rateLimit.lockout_until,
        rateLimit.failed_attempts
      );
    } catch (error) {
      throw new DatabaseError(`Failed to upsert rate limit for user ${rateLimit.user_id}`, error);
    }
  }

  public getRateLimitByUserId(userId: string): RateLimit | undefined {
    this.ensureNotClosed();
    this.validateRequiredString(userId, 'userId');

    try {
      const stmt = this.db.prepare('SELECT * FROM rate_limits WHERE user_id = ?');
      return stmt.get(userId) as RateLimit | undefined;
    } catch (error) {
      throw new DatabaseError(`Failed to get rate limit for user ${userId}`, error);
    }
  }

  // User Reputation Methods
  public upsertUserReputation(reputation: UserReputation): void {
    this.ensureNotClosed();
    this.validateRequiredString(reputation.user_id, 'user_id');

    if (typeof reputation.trust_score !== 'number' || reputation.trust_score < 0) {
      throw new DatabaseError(`trust_score must be a non-negative number, got: ${reputation.trust_score}`);
    }

    this.validatePositiveInteger(reputation.total_requests, 'total_requests');
    this.validatePositiveInteger(reputation.blocked_attempts, 'blocked_attempts');

    if (reputation.is_allowlisted !== 0 && reputation.is_allowlisted !== 1) {
      throw new DatabaseError(`is_allowlisted must be 0 or 1, got: ${reputation.is_allowlisted}`);
    }

    if (reputation.is_blocklisted !== 0 && reputation.is_blocklisted !== 1) {
      throw new DatabaseError(`is_blocklisted must be 0 or 1, got: ${reputation.is_blocklisted}`);
    }

    try {
      const stmt = this.db.prepare(`
        INSERT INTO user_reputation (
          user_id, trust_score, total_requests, blocked_attempts, last_violation, is_allowlisted, is_blocklisted, notes
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(user_id) DO UPDATE SET
          trust_score = excluded.trust_score,
          total_requests = excluded.total_requests,
          blocked_attempts = excluded.blocked_attempts,
          last_violation = excluded.last_violation,
          is_allowlisted = excluded.is_allowlisted,
          is_blocklisted = excluded.is_blocklisted,
          notes = excluded.notes
      `);

      stmt.run(
        reputation.user_id,
        reputation.trust_score,
        reputation.total_requests,
        reputation.blocked_attempts,
        reputation.last_violation,
        reputation.is_allowlisted,
        reputation.is_blocklisted,
        reputation.notes
      );
    } catch (error) {
      throw new DatabaseError(`Failed to upsert user reputation for user ${reputation.user_id}`, error);
    }
  }

  public getUserReputation(userId: string): UserReputation | undefined {
    this.ensureNotClosed();
    this.validateRequiredString(userId, 'userId');

    try {
      const stmt = this.db.prepare('SELECT * FROM user_reputation WHERE user_id = ?');
      return stmt.get(userId) as UserReputation | undefined;
    } catch (error) {
      throw new DatabaseError(`Failed to get user reputation for user ${userId}`, error);
    }
  }

  // Attack Patterns Methods
  public upsertAttackPattern(pattern: AttackPattern): number {
    this.ensureNotClosed();
    this.validateRequiredString(pattern.pattern, 'pattern');
    this.validateRequiredString(pattern.category, 'category');
    this.validateSeverity(pattern.severity);
    this.validateRequiredString(pattern.language, 'language');
    this.validatePositiveInteger(pattern.times_matched, 'times_matched');

    if (pattern.is_custom !== 0 && pattern.is_custom !== 1) {
      throw new DatabaseError(`is_custom must be 0 or 1, got: ${pattern.is_custom}`);
    }

    if (pattern.enabled !== 0 && pattern.enabled !== 1) {
      throw new DatabaseError(`enabled must be 0 or 1, got: ${pattern.enabled}`);
    }

    try {
      const stmt = this.db.prepare(`
        INSERT INTO attack_patterns (
          pattern, category, severity, language, times_matched, last_matched, is_custom, enabled
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(pattern) DO UPDATE SET
          category = excluded.category,
          severity = excluded.severity,
          language = excluded.language,
          times_matched = excluded.times_matched,
          last_matched = excluded.last_matched,
          is_custom = excluded.is_custom,
          enabled = excluded.enabled
      `);

      const result = stmt.run(
        pattern.pattern,
        pattern.category,
        pattern.severity,
        pattern.language,
        pattern.times_matched,
        pattern.last_matched,
        pattern.is_custom,
        pattern.enabled
      );

      return result.lastInsertRowid as number;
    } catch (error) {
      throw new DatabaseError(`Failed to upsert attack pattern: ${pattern.pattern}`, error);
    }
  }

  public getAttackPatternByPattern(pattern: string): AttackPattern | undefined {
    this.ensureNotClosed();
    this.validateRequiredString(pattern, 'pattern');

    try {
      const stmt = this.db.prepare('SELECT * FROM attack_patterns WHERE pattern = ?');
      return stmt.get(pattern) as AttackPattern | undefined;
    } catch (error) {
      throw new DatabaseError(`Failed to get attack pattern: ${pattern}`, error);
    }
  }

  public getAttackPatternsByCategory(category: string, limit: number = 100): AttackPattern[] {
    this.ensureNotClosed();
    this.validateRequiredString(category, 'category');
    this.validatePositiveInteger(limit, 'limit');

    try {
      const stmt = this.db.prepare(`
        SELECT * FROM attack_patterns
        WHERE category = ?
        ORDER BY times_matched DESC
        LIMIT ?
      `);
      return stmt.all(category, limit) as AttackPattern[];
    } catch (error) {
      throw new DatabaseError(`Failed to get attack patterns by category ${category}`, error);
    }
  }

  // Notifications Log Methods
  public insertNotificationLog(log: NotificationLog): number {
    this.ensureNotClosed();
    this.validateRequiredString(log.channel, 'channel');
    this.validateSeverity(log.severity);
    this.validateRequiredString(log.message, 'message');
    this.validateRequiredString(log.delivery_status, 'delivery_status');
    this.validatePositiveInteger(log.event_id, 'event_id');

    try {
      const stmt = this.db.prepare(`
        INSERT INTO notifications_log (
          channel, severity, message, delivery_status, event_id
        ) VALUES (?, ?, ?, ?, ?)
      `);

      const result = stmt.run(
        log.channel,
        log.severity,
        log.message,
        log.delivery_status,
        log.event_id
      );

      return result.lastInsertRowid as number;
    } catch (error) {
      throw new DatabaseError(`Failed to insert notification log for event ${log.event_id}`, error);
    }
  }

  public getNotificationLogsByEventId(eventId: number): NotificationLog[] {
    this.ensureNotClosed();
    this.validatePositiveInteger(eventId, 'eventId');

    try {
      const stmt = this.db.prepare('SELECT * FROM notifications_log WHERE event_id = ? ORDER BY timestamp DESC');
      return stmt.all(eventId) as NotificationLog[];
    } catch (error) {
      throw new DatabaseError(`Failed to get notification logs for event ${eventId}`, error);
    }
  }

  // Utility Methods
  public close(): void {
    if (this.isClosed) {
      return; // Already closed, no-op
    }

    try {
      this.db.close();
      this.isClosed = true;
    } catch (error) {
      throw new DatabaseError('Failed to close database connection', error);
    }
  }

  public vacuum(): void {
    this.ensureNotClosed();

    try {
      this.db.exec('VACUUM');
    } catch (error) {
      throw new DatabaseError('Failed to vacuum database', error);
    }
  }

  public deleteOldEvents(daysToKeep: number): number {
    this.ensureNotClosed();

    // Validate that daysToKeep is a positive integer to prevent SQL injection
    if (!Number.isInteger(daysToKeep) || daysToKeep < 0) {
      throw new DatabaseError(`daysToKeep must be a positive integer, got: ${daysToKeep}`);
    }

    try {
      const stmt = this.db.prepare(`
        DELETE FROM security_events
        WHERE timestamp < datetime('now', '-' || ? || ' days')
      `);
      const result = stmt.run(daysToKeep);
      return result.changes;
    } catch (error) {
      throw new DatabaseError(`Failed to delete events older than ${daysToKeep} days`, error);
    }
  }
}

import * as fs from 'fs';
import * as path from 'path';
import { AsyncQueue } from './async-queue';
import { Severity, Action } from '../types';

/**
 * Log levels in order of severity
 */
export enum LogLevel {
  DEBUG = 'DEBUG',
  INFO = 'INFO',
  WARN = 'WARN',
  ERROR = 'ERROR'
}

/**
 * Configuration options for Logger
 */
export interface LoggerOptions {
  filePath: string;
  level: LogLevel;
  batchSize?: number;
  flushInterval?: number;
  maxFileSize?: number; // in bytes
  maxRotatedFiles?: number;
}

/**
 * Security event log entry
 */
export interface SecurityEventLog {
  severity: Severity;
  action: Action;
  userId: string;
  module: string;
  fingerprint: string;
  message: string;
  metadata?: Record<string, any>;
}

/**
 * Logger provides structured JSON logging to file with buffered writes,
 * log rotation, and integration with AsyncQueue.
 *
 * Features:
 * - Structured JSON logging
 * - Buffered writes via AsyncQueue
 * - Automatic log rotation by file size
 * - Configurable log levels
 * - Manual flush support
 *
 * @example
 * ```typescript
 * const logger = new Logger({
 *   filePath: '/path/to/logs/security.log',
 *   level: LogLevel.INFO,
 *   maxFileSize: 10 * 1024 * 1024, // 10MB
 *   maxRotatedFiles: 5
 * });
 *
 * logger.info('Application started');
 * logger.logSecurityEvent({
 *   severity: Severity.HIGH,
 *   action: Action.BLOCK,
 *   userId: 'user-123',
 *   module: 'prompt_injection',
 *   fingerprint: 'fp-123',
 *   message: 'Malicious input detected'
 * });
 *
 * await logger.flush();
 * logger.stop();
 * ```
 */
export class Logger {
  private readonly filePath: string;
  private readonly level: LogLevel;
  private readonly maxFileSize: number;
  private readonly maxRotatedFiles: number;
  private readonly queue: AsyncQueue;
  private readonly levelPriority: Record<LogLevel, number> = {
    [LogLevel.DEBUG]: 0,
    [LogLevel.INFO]: 1,
    [LogLevel.WARN]: 2,
    [LogLevel.ERROR]: 3
  };

  /**
   * Creates a new Logger instance
   *
   * @param options - Logger configuration
   * @throws Error if filePath is missing
   */
  constructor(options: LoggerOptions) {
    if (!options.filePath || options.filePath.trim().length === 0) {
      throw new Error('Log file path is required');
    }

    this.filePath = options.filePath;
    this.level = options.level;
    this.maxFileSize = options.maxFileSize ?? 10 * 1024 * 1024; // Default 10MB
    this.maxRotatedFiles = options.maxRotatedFiles ?? 5;

    // Ensure log directory exists
    const logDir = path.dirname(this.filePath);
    if (!fs.existsSync(logDir)) {
      fs.mkdirSync(logDir, { recursive: true });
    }

    // Initialize AsyncQueue for buffered writes
    this.queue = new AsyncQueue({
      batchSize: options.batchSize ?? 50,
      flushInterval: options.flushInterval ?? 100,
      onBatch: async (logs: string[]) => {
        await this.writeBatch(logs);
      }
    });
  }

  /**
   * Log a debug message
   */
  debug(message: string, metadata?: Record<string, any>): void {
    this.log(LogLevel.DEBUG, message, metadata);
  }

  /**
   * Log an info message
   */
  info(message: string, metadata?: Record<string, any>): void {
    this.log(LogLevel.INFO, message, metadata);
  }

  /**
   * Log a warning message
   */
  warn(message: string, metadata?: Record<string, any>): void {
    this.log(LogLevel.WARN, message, metadata);
  }

  /**
   * Log an error message
   */
  error(message: string, metadata?: Record<string, any>): void {
    this.log(LogLevel.ERROR, message, metadata);
  }

  /**
   * Log a structured security event
   */
  logSecurityEvent(event: SecurityEventLog): void {
    const logData: Record<string, any> = {
      severity: event.severity,
      action: event.action,
      userId: event.userId,
      module: event.module,
      fingerprint: event.fingerprint
    };

    // Include metadata if provided
    if (event.metadata) {
      logData.metadata = event.metadata;
    }

    this.log(LogLevel.INFO, event.message, logData);
  }

  /**
   * Flush all pending log entries
   */
  async flush(): Promise<void> {
    await this.queue.flush();
  }

  /**
   * Stop the logger and flush remaining logs
   */
  stop(): void {
    // Flush synchronously before stopping
    const remainingSize = this.queue.size();
    if (remainingSize > 0) {
      // Force flush remaining logs
      this.queue.flush().catch(err => {
        console.error('Error flushing logs on stop:', err);
      });
    }
    this.queue.stop();
  }

  /**
   * Log a message at the specified level
   * @private
   */
  private log(level: LogLevel, message: string, metadata?: Record<string, any>): void {
    // Check if this message should be logged based on level
    if (this.levelPriority[level] < this.levelPriority[this.level]) {
      return;
    }

    const logEntry = {
      timestamp: new Date().toISOString(),
      level,
      message,
      ...metadata
    };

    const logLine = JSON.stringify(logEntry);
    this.queue.enqueue(logLine);
  }

  /**
   * Write a batch of log entries to file
   * @private
   */
  private async writeBatch(logs: string[]): Promise<void> {
    try {
      // Write logs to file
      const content = logs.join('\n') + '\n';
      fs.appendFileSync(this.filePath, content, 'utf8');

      // Check if rotation is needed after write
      await this.rotateIfNeeded();
    } catch (error) {
      // Log to console if file write fails
      console.error('Failed to write logs to file:', error);
    }
  }

  /**
   * Rotate log file if it exceeds max size
   * @private
   */
  private async rotateIfNeeded(): Promise<void> {
    try {
      // Check if file exists and get size
      if (!fs.existsSync(this.filePath)) {
        return;
      }

      const stats = fs.statSync(this.filePath);
      if (stats.size < this.maxFileSize) {
        return;
      }

      // Rotate the log file
      const timestamp = new Date().toISOString().replace(/:/g, '-').replace(/\..+/, '');
      const rotatedPath = `${this.filePath}.${timestamp}`;

      fs.renameSync(this.filePath, rotatedPath);

      // Clean up old rotated files
      this.cleanupOldRotatedFiles();
    } catch (error) {
      console.error('Error during log rotation:', error);
    }
  }

  /**
   * Remove old rotated files beyond maxRotatedFiles limit
   * @private
   */
  private cleanupOldRotatedFiles(): void {
    try {
      const logDir = path.dirname(this.filePath);
      const logFileName = path.basename(this.filePath);

      // Get all rotated files
      const files = fs.readdirSync(logDir);
      const rotatedFiles = files
        .filter(f => f.startsWith(logFileName + '.'))
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          mtime: fs.statSync(path.join(logDir, f)).mtime.getTime()
        }))
        .sort((a, b) => b.mtime - a.mtime); // Sort by modification time, newest first

      // Remove old files beyond the limit
      if (rotatedFiles.length > this.maxRotatedFiles) {
        const filesToDelete = rotatedFiles.slice(this.maxRotatedFiles);
        filesToDelete.forEach(file => {
          try {
            fs.unlinkSync(file.path);
          } catch (error) {
            console.error(`Failed to delete old log file ${file.name}:`, error);
          }
        });
      }
    } catch (error) {
      console.error('Error cleaning up old rotated files:', error);
    }
  }
}

import { Severity, Action, NotificationConfig } from '../types';
import * as https from 'https';
import * as http from 'http';
import { URL } from 'url';

/**
 * Notification payload
 */
export interface NotificationPayload {
  severity: Severity;
  action: Action;
  userId: string;
  module: string;
  fingerprint: string;
  message: string;
  timestamp: string;
  metadata?: Record<string, any>;
}

/**
 * Result of notification delivery
 */
export interface NotificationResult {
  sent: boolean;
  channels: string[];
  reason?: string;
  errors?: Record<string, string>;
}

/**
 * NotificationSystem handles async delivery of security notifications
 * to various channels (webhook, Slack, Discord).
 *
 * Features:
 * - Multiple channel support (webhook, Slack, Discord)
 * - Async delivery with error handling
 * - Severity threshold filtering
 * - Graceful degradation on channel failures
 *
 * @example
 * ```typescript
 * const notifier = new NotificationSystem(config);
 * const result = await notifier.notify({
 *   severity: Severity.CRITICAL,
 *   action: Action.BLOCK_NOTIFY,
 *   userId: 'user-123',
 *   module: 'prompt_injection',
 *   fingerprint: 'fp-123',
 *   message: 'Critical security threat detected',
 *   timestamp: new Date().toISOString()
 * });
 * ```
 */
export class NotificationSystem {
  private readonly config: NotificationConfig;
  private readonly severityWeight: Record<Severity, number> = {
    [Severity.SAFE]: 0,
    [Severity.LOW]: 1,
    [Severity.MEDIUM]: 2,
    [Severity.HIGH]: 3,
    [Severity.CRITICAL]: 4
  };

  /**
   * Creates a new NotificationSystem instance
   *
   * @param config - Notification configuration
   * @throws Error if config is missing
   */
  constructor(config: NotificationConfig) {
    if (!config) {
      throw new Error('Configuration is required');
    }
    this.config = config;
  }

  /**
   * Send notification to all enabled channels
   *
   * @param payload - Notification payload
   * @returns NotificationResult with delivery status
   */
  async notify(payload: NotificationPayload): Promise<NotificationResult> {
    // Check if notifications are enabled
    if (!this.config.enabled) {
      return {
        sent: false,
        channels: [],
        reason: 'Notifications are disabled in configuration'
      };
    }

    // Check severity threshold
    if (!this.meetsThreshold(payload.severity)) {
      return {
        sent: false,
        channels: [],
        reason: `Severity ${payload.severity} is below threshold ${this.config.severity_threshold}`
      };
    }

    // Collect enabled channels
    const enabledChannels = this.getEnabledChannels();
    if (enabledChannels.length === 0) {
      return {
        sent: false,
        channels: [],
        reason: 'No notification channels are configured or enabled'
      };
    }

    // Send to all channels
    const results = await Promise.allSettled(
      enabledChannels.map(channel => this.sendToChannel(channel, payload))
    );

    // Collect successful channels and errors
    const successfulChannels: string[] = [];
    const errors: Record<string, string> = {};

    results.forEach((result, index) => {
      const channel = enabledChannels[index];
      if (result.status === 'fulfilled' && result.value) {
        successfulChannels.push(channel);
      } else if (result.status === 'rejected') {
        errors[channel] = result.reason?.message || 'Unknown error';
      }
    });

    return {
      sent: successfulChannels.length > 0,
      channels: successfulChannels,
      errors: Object.keys(errors).length > 0 ? errors : undefined
    };
  }

  /**
   * Check if severity meets threshold
   * @private
   */
  private meetsThreshold(severity: Severity): boolean {
    return this.severityWeight[severity] >= this.severityWeight[this.config.severity_threshold];
  }

  /**
   * Get list of enabled channels
   * @private
   */
  private getEnabledChannels(): string[] {
    const channels: string[] = [];

    if (this.config.channels.webhook?.enabled) {
      channels.push('webhook');
    }
    if (this.config.channels.slack?.enabled) {
      channels.push('slack');
    }
    if (this.config.channels.discord?.enabled) {
      channels.push('discord');
    }

    return channels;
  }

  /**
   * Send notification to a specific channel
   * @private
   */
  private async sendToChannel(channel: string, payload: NotificationPayload): Promise<boolean> {
    switch (channel) {
      case 'webhook':
        return this.sendWebhook(payload);
      case 'slack':
        return this.sendSlack(payload);
      case 'discord':
        return this.sendDiscord(payload);
      default:
        throw new Error(`Unknown channel: ${channel}`);
    }
  }

  /**
   * Send generic webhook notification
   * @private
   */
  private async sendWebhook(payload: NotificationPayload): Promise<boolean> {
    const webhookUrl = this.config.channels.webhook?.url;
    if (!webhookUrl) {
      throw new Error('Webhook URL not configured');
    }

    const data = JSON.stringify(payload);

    return this.sendHttpRequest(webhookUrl, data);
  }

  /**
   * Send Slack notification
   * @private
   */
  private async sendSlack(payload: NotificationPayload): Promise<boolean> {
    const webhookUrl = this.config.channels.slack?.webhook_url;
    if (!webhookUrl) {
      throw new Error('Slack webhook URL not configured');
    }

    // Format Slack message
    const slackPayload = {
      text: `*OpenClaw Security Alert*`,
      attachments: [
        {
          color: this.getSeverityColor(payload.severity),
          fields: [
            {
              title: 'Severity',
              value: payload.severity,
              short: true
            },
            {
              title: 'Action',
              value: payload.action,
              short: true
            },
            {
              title: 'Module',
              value: payload.module,
              short: true
            },
            {
              title: 'User ID',
              value: payload.userId,
              short: true
            },
            {
              title: 'Message',
              value: payload.message,
              short: false
            },
            {
              title: 'Fingerprint',
              value: payload.fingerprint,
              short: false
            }
          ],
          footer: 'OpenClaw Security Suite',
          ts: Math.floor(new Date(payload.timestamp).getTime() / 1000)
        }
      ]
    };

    const data = JSON.stringify(slackPayload);
    return this.sendHttpRequest(webhookUrl, data);
  }

  /**
   * Send Discord notification
   * @private
   */
  private async sendDiscord(payload: NotificationPayload): Promise<boolean> {
    const webhookUrl = this.config.channels.discord?.webhook_url;
    if (!webhookUrl) {
      throw new Error('Discord webhook URL not configured');
    }

    // Format Discord message
    const discordPayload = {
      content: `**OpenClaw Security Alert**`,
      embeds: [
        {
          title: `${payload.severity} Severity Event`,
          description: payload.message,
          color: this.getDiscordColor(payload.severity),
          fields: [
            {
              name: 'Severity',
              value: payload.severity,
              inline: true
            },
            {
              name: 'Action',
              value: payload.action,
              inline: true
            },
            {
              name: 'Module',
              value: payload.module,
              inline: true
            },
            {
              name: 'User ID',
              value: payload.userId,
              inline: true
            },
            {
              name: 'Fingerprint',
              value: payload.fingerprint,
              inline: false
            }
          ],
          timestamp: payload.timestamp,
          footer: {
            text: 'OpenClaw Security Suite'
          }
        }
      ]
    };

    const data = JSON.stringify(discordPayload);
    return this.sendHttpRequest(webhookUrl, data);
  }

  /**
   * Send HTTP request to webhook URL
   * @private
   */
  private async sendHttpRequest(url: string, data: string): Promise<boolean> {
    return new Promise((resolve, reject) => {
      try {
        const parsedUrl = new URL(url);
        const httpModule = parsedUrl.protocol === 'https:' ? https : http;

        const options = {
          hostname: parsedUrl.hostname,
          port: parsedUrl.port || (parsedUrl.protocol === 'https:' ? 443 : 80),
          path: parsedUrl.pathname + parsedUrl.search,
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(data)
          }
        };

        const req = httpModule.request(options, (res) => {
          let responseData = '';

          res.on('data', (chunk) => {
            responseData += chunk;
          });

          res.on('end', () => {
            if (res.statusCode && res.statusCode >= 200 && res.statusCode < 300) {
              resolve(true);
            } else {
              reject(new Error(`HTTP ${res.statusCode}: ${responseData}`));
            }
          });
        });

        req.on('error', (error) => {
          reject(error);
        });

        req.write(data);
        req.end();
      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * Get Slack color for severity
   * @private
   */
  private getSeverityColor(severity: Severity): string {
    switch (severity) {
      case Severity.CRITICAL:
        return 'danger'; // Red
      case Severity.HIGH:
        return 'danger'; // Red
      case Severity.MEDIUM:
        return 'warning'; // Orange
      case Severity.LOW:
        return 'good'; // Green
      case Severity.SAFE:
        return 'good'; // Green
      default:
        return '#cccccc'; // Gray
    }
  }

  /**
   * Get Discord color (decimal) for severity
   * @private
   */
  private getDiscordColor(severity: Severity): number {
    switch (severity) {
      case Severity.CRITICAL:
        return 0xff0000; // Red
      case Severity.HIGH:
        return 0xff6600; // Orange-red
      case Severity.MEDIUM:
        return 0xffaa00; // Orange
      case Severity.LOW:
        return 0xffdd00; // Yellow
      case Severity.SAFE:
        return 0x00ff00; // Green
      default:
        return 0xcccccc; // Gray
    }
  }
}

import { SecurityConfig, ValidationResult, Finding, Severity, Action } from '../types';
import { DatabaseManager, SecurityEvent } from './database-manager';
import { SeverityScorer } from './severity-scorer';
import { ActionEngine } from './action-engine';
import { AsyncQueue } from './async-queue';
import { PromptInjectionDetector } from '../modules/prompt-injection/detector';
import { CommandValidator } from '../modules/command-validator/validator';
import { URLValidator } from '../modules/url-validator/validator';
import { PathValidator } from '../modules/path-validator/validator';
import { SecretDetector } from '../modules/secret-detector/detector';
import { ContentScanner } from '../modules/content-scanner/scanner';
import { InjectionValidator } from '../modules/injection-validator/validator';
import { ExfiltrationDetector } from '../modules/exfiltration-detector/detector';
import { CodeExecutionDetector } from '../modules/code-execution-detector/detector';
import { SerializationDetector } from '../modules/serialization-detector/detector';
import * as crypto from 'crypto';

/**
 * Validation metadata
 */
export interface ValidationMetadata {
  userId: string;
  sessionId: string;
  context?: Record<string, any>;
}

/**
 * SecurityEngine is the main orchestrator that coordinates all detection modules,
 * severity scoring, action determination, and async writes.
 *
 * Architecture:
 * - Runs all 10 detection modules in parallel
 * - Aggregates findings with SeverityScorer
 * - Determines action with ActionEngine
 * - Returns results in ~20-50ms
 * - Queues DB writes and notifications asynchronously
 *
 * @example
 * ```typescript
 * const config = await ConfigManager.load('security-config.yaml');
 * const dbManager = new DatabaseManager('.openclaw-sec.db');
 * const engine = new SecurityEngine(config, dbManager);
 *
 * const result = await engine.validate('User input text', {
 *   userId: 'user-123',
 *   sessionId: 'session-456'
 * });
 *
 * console.log(result.severity); // SAFE, LOW, MEDIUM, HIGH, or CRITICAL
 * console.log(result.action); // allow, log, warn, block, or block_notify
 *
 * await engine.stop(); // Cleanup
 * ```
 */
interface CacheEntry {
  findings: Finding[];
  severity: Severity;
  timestamp: number;
}

export class SecurityEngine {
  private readonly config: SecurityConfig;
  private readonly dbManager: DatabaseManager;
  private readonly severityScorer: SeverityScorer;
  private readonly actionEngine: ActionEngine;
  private readonly writeQueue: AsyncQueue;

  // Validation result cache (LRU)
  private readonly cache: Map<string, CacheEntry> = new Map();
  private readonly cacheSize: number;
  private readonly cacheTtlMs: number;

  // Detection modules
  private readonly promptInjectionDetector: PromptInjectionDetector | null = null;
  private readonly commandValidator: CommandValidator | null = null;
  private readonly urlValidator: URLValidator | null = null;
  private readonly pathValidator: PathValidator | null = null;
  private readonly secretDetector: SecretDetector | null = null;
  private readonly contentScanner: ContentScanner | null = null;
  private readonly injectionValidator: InjectionValidator | null = null;
  private readonly exfiltrationDetector: ExfiltrationDetector | null = null;
  private readonly codeExecutionDetector: CodeExecutionDetector | null = null;
  private readonly serializationDetector: SerializationDetector | null = null;

  /**
   * Creates a new SecurityEngine instance
   *
   * @param config - Security configuration
   * @param dbManager - Database manager
   * @throws Error if config or dbManager is missing
   */
  constructor(config: SecurityConfig, dbManager?: DatabaseManager | null) {
    if (!config) {
      throw new Error('Configuration is required');
    }

    this.config = config;
    this.dbManager = dbManager!;
    this.severityScorer = new SeverityScorer();
    this.actionEngine = new ActionEngine(config, dbManager);
    this.cacheSize = config.cacheSize ?? 1000;
    this.cacheTtlMs = config.cacheTtlMs ?? 5 * 60 * 1000; // 5 minutes

    // Initialize async write queue (skip DB writes if no dbManager)
    this.writeQueue = new AsyncQueue({
      batchSize: 50,
      flushInterval: 100,
      onBatch: async (events: SecurityEvent[]) => {
        if (!this.dbManager) return; // Skip DB writes in NO_DB mode
        try {
          events.forEach(event => {
            this.dbManager.insertEvent(event);
          });
        } catch (error) {
          console.error('Error writing security events to database:', error);
        }
      }
    });

    // Initialize enabled modules
    if (config.modules.prompt_injection?.enabled) {
      this.promptInjectionDetector = new PromptInjectionDetector(config.modules.prompt_injection);
    }
    if (config.modules.command_validator?.enabled) {
      this.commandValidator = new CommandValidator(config.modules.command_validator);
    }
    if (config.modules.url_validator?.enabled) {
      this.urlValidator = new URLValidator(config.modules.url_validator);
    }
    if (config.modules.path_validator?.enabled) {
      this.pathValidator = new PathValidator(config.modules.path_validator);
    }
    if (config.modules.secret_detector?.enabled) {
      this.secretDetector = new SecretDetector(config.modules.secret_detector);
    }
    if (config.modules.content_scanner?.enabled) {
      this.contentScanner = new ContentScanner(config.modules.content_scanner);
    }
    if (config.modules.injection_validator?.enabled) {
      this.injectionValidator = new InjectionValidator(config.modules.injection_validator);
    }
    if (config.modules.exfiltration_detector?.enabled) {
      this.exfiltrationDetector = new ExfiltrationDetector(config.modules.exfiltration_detector);
    }
    if (config.modules.code_execution_detector?.enabled) {
      this.codeExecutionDetector = new CodeExecutionDetector(config.modules.code_execution_detector);
    }
    if (config.modules.serialization_detector?.enabled) {
      this.serializationDetector = new SerializationDetector(config.modules.serialization_detector);
    }
  }

  /**
   * Validate input text against all security modules
   *
   * @param text - Input text to validate
   * @param metadata - Validation metadata (userId, sessionId, etc.)
   * @returns ValidationResult with severity, action, and findings
   * @throws Error if metadata is invalid
   */
  async validate(text: string, metadata: ValidationMetadata): Promise<ValidationResult> {
    // Validate metadata
    if (!metadata.userId || metadata.userId.trim().length === 0) {
      throw new Error('User ID is required in validation metadata');
    }

    if (!metadata.sessionId || metadata.sessionId.trim().length === 0) {
      throw new Error('Session ID is required in validation metadata');
    }

    // Check if security is enabled
    if (!this.config.enabled) {
      return this.createSafeResult(text);
    }

    // Generate fingerprint for cache lookup
    const fingerprint = this.generateFingerprint(text);

    // Check cache
    const cached = this.getCacheEntry(fingerprint);
    if (cached) {
      // Re-run action engine for the current user (action is user-specific)
      const actionResult = await this.actionEngine.determineAction(
        cached.severity,
        metadata.userId
      );

      const result: ValidationResult = {
        severity: cached.severity,
        action: actionResult.action,
        findings: cached.findings,
        fingerprint,
        timestamp: new Date(),
        normalizedText: this.normalizeText(text),
        recommendations: this.generateRecommendations(cached.findings, actionResult.action)
      };

      this.queueDatabaseWrite(result, metadata);
      return result;
    }

    // Compute input entropy before module dispatch
    const entropy = this.calculateEntropy(text);

    // Collect all findings
    let allFindings: Finding[];

    if (this.config.earlyExitOnCritical) {
      // Two-phase execution: run fast modules first
      allFindings = await this.runWithEarlyExit(text);
    } else {
      // Standard parallel execution
      allFindings = await this.runAllModules(text);
    }

    // Inject synthetic entropy finding if entropy is high
    if (entropy > 4.5) {
      allFindings.push({
        module: 'entropy_analysis',
        pattern: {
          id: 'entropy_001',
          category: 'high_entropy',
          pattern: '',
          severity: Severity.MEDIUM,
          language: 'all',
          description: `Input has high Shannon entropy (${entropy.toFixed(2)} bits/char), indicating possible obfuscation`,
          examples: [],
          falsePositiveRisk: 'medium',
          enabled: true,
          tags: ['entropy', 'obfuscation', 'anomaly']
        },
        matchedText: text.substring(0, 50) + (text.length > 50 ? '...' : ''),
        severity: Severity.MEDIUM,
        metadata: {
          entropy: entropy,
          textLength: text.length,
          category: 'high_entropy'
        }
      });
    }

    // Calculate severity
    const severityResult = this.severityScorer.calculateSeverity(allFindings);

    // Store in cache
    this.setCacheEntry(fingerprint, {
      findings: allFindings,
      severity: severityResult.severity,
      timestamp: Date.now()
    });

    // Determine action
    const actionResult = await this.actionEngine.determineAction(
      severityResult.severity,
      metadata.userId
    );

    // Create validation result
    const result: ValidationResult = {
      severity: severityResult.severity,
      action: actionResult.action,
      findings: allFindings,
      fingerprint,
      timestamp: new Date(),
      normalizedText: this.normalizeText(text),
      recommendations: this.generateRecommendations(allFindings, actionResult.action)
    };

    // Queue async database write
    this.queueDatabaseWrite(result, metadata);

    return result;
  }

  /**
   * Run all detection modules in parallel (standard mode)
   * @private
   */
  private async runAllModules(text: string): Promise<Finding[]> {
    const detectionPromises: Promise<Finding[]>[] = [];

    if (this.promptInjectionDetector) {
      detectionPromises.push(this.promptInjectionDetector.scan(text).catch(() => []));
    }
    if (this.commandValidator) {
      detectionPromises.push(this.commandValidator.validate(text).catch(() => []));
    }
    if (this.urlValidator) {
      detectionPromises.push(this.urlValidator.validate(text).catch(() => []));
    }
    if (this.pathValidator) {
      detectionPromises.push(this.pathValidator.validate(text).catch(() => []));
    }
    if (this.secretDetector) {
      detectionPromises.push(this.secretDetector.scan(text).catch(() => []));
    }
    if (this.contentScanner) {
      detectionPromises.push(this.contentScanner.scan(text).catch(() => []));
    }
    if (this.injectionValidator) {
      detectionPromises.push(this.injectionValidator.validate(text).catch(() => []));
    }
    if (this.exfiltrationDetector) {
      detectionPromises.push(this.exfiltrationDetector.scan(text).catch(() => []));
    }
    if (this.codeExecutionDetector) {
      detectionPromises.push(this.codeExecutionDetector.scan(text).catch(() => []));
    }
    if (this.serializationDetector) {
      detectionPromises.push(this.serializationDetector.scan(text).catch(() => []));
    }

    const results = await Promise.all(detectionPromises);
    return results.flat();
  }

  /**
   * Two-phase execution with early exit on CRITICAL findings
   * Phase 1: Run fast modules (command, path, injection validators)
   * Phase 2: If no CRITICAL found, run remaining modules
   * @private
   */
  private async runWithEarlyExit(text: string): Promise<Finding[]> {
    // Phase 1: Fast regex-only modules
    const fastPromises: Promise<Finding[]>[] = [];

    if (this.commandValidator) {
      fastPromises.push(this.commandValidator.validate(text).catch(() => []));
    }
    if (this.pathValidator) {
      fastPromises.push(this.pathValidator.validate(text).catch(() => []));
    }
    if (this.injectionValidator) {
      fastPromises.push(this.injectionValidator.validate(text).catch(() => []));
    }

    const fastResults = await Promise.all(fastPromises);
    const fastFindings = fastResults.flat();

    // Check for CRITICAL
    const hasCritical = fastFindings.some(f => f.severity === Severity.CRITICAL);
    if (hasCritical) {
      return fastFindings;
    }

    // Phase 2: Run remaining modules
    const slowPromises: Promise<Finding[]>[] = [];

    if (this.promptInjectionDetector) {
      slowPromises.push(this.promptInjectionDetector.scan(text).catch(() => []));
    }
    if (this.urlValidator) {
      slowPromises.push(this.urlValidator.validate(text).catch(() => []));
    }
    if (this.secretDetector) {
      slowPromises.push(this.secretDetector.scan(text).catch(() => []));
    }
    if (this.contentScanner) {
      slowPromises.push(this.contentScanner.scan(text).catch(() => []));
    }
    if (this.exfiltrationDetector) {
      slowPromises.push(this.exfiltrationDetector.scan(text).catch(() => []));
    }
    if (this.codeExecutionDetector) {
      slowPromises.push(this.codeExecutionDetector.scan(text).catch(() => []));
    }
    if (this.serializationDetector) {
      slowPromises.push(this.serializationDetector.scan(text).catch(() => []));
    }

    const slowResults = await Promise.all(slowPromises);
    return [...fastFindings, ...slowResults.flat()];
  }

  /**
   * Stop the security engine and flush pending writes
   */
  async stop(): Promise<void> {
    await this.writeQueue.flush();
    this.writeQueue.stop();
  }

  /**
   * Create a safe result for clean input
   * @private
   */
  private createSafeResult(text: string): ValidationResult {
    return {
      severity: Severity.SAFE,
      action: Action.ALLOW,
      findings: [],
      fingerprint: this.generateFingerprint(text),
      timestamp: new Date(),
      normalizedText: this.normalizeText(text),
      recommendations: []
    };
  }

  /**
   * Generate a fingerprint for the input text
   * @private
   */
  private generateFingerprint(text: string): string {
    const normalized = this.normalizeText(text);
    return crypto.createHash('sha256').update(normalized).digest('hex').substring(0, 16);
  }

  /**
   * Normalize text for fingerprinting
   * @private
   */
  private normalizeText(text: string): string {
    return text.toLowerCase().replace(/\s+/g, ' ').trim();
  }

  /**
   * Calculate Shannon entropy of input text (bits per character)
   * @private
   */
  private calculateEntropy(text: string): number {
    if (text.length === 0) return 0;

    const freq = new Map<string, number>();
    for (const char of text) {
      freq.set(char, (freq.get(char) || 0) + 1);
    }

    let entropy = 0;
    const len = text.length;
    for (const count of freq.values()) {
      const p = count / len;
      if (p > 0) {
        entropy -= p * Math.log2(p);
      }
    }

    return entropy;
  }

  /**
   * Get a cache entry if it exists and is not expired
   * @private
   */
  private getCacheEntry(fingerprint: string): CacheEntry | null {
    const entry = this.cache.get(fingerprint);
    if (!entry) return null;

    // Check TTL
    if (Date.now() - entry.timestamp > this.cacheTtlMs) {
      this.cache.delete(fingerprint);
      return null;
    }

    return entry;
  }

  /**
   * Set a cache entry, evicting oldest if at capacity
   * @private
   */
  private setCacheEntry(fingerprint: string, entry: CacheEntry): void {
    // Evict oldest entry if at capacity
    if (this.cache.size >= this.cacheSize && !this.cache.has(fingerprint)) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey !== undefined) {
        this.cache.delete(firstKey);
      }
    }

    this.cache.set(fingerprint, entry);
  }

  /**
   * Generate actionable recommendations based on findings
   * @private
   */
  private generateRecommendations(findings: Finding[], action: Action): string[] {
    const recommendations: string[] = [];

    if (findings.length === 0) {
      return recommendations;
    }

    // Group findings by module
    const moduleGroups = new Map<string, Finding[]>();
    findings.forEach(finding => {
      const existing = moduleGroups.get(finding.module) || [];
      existing.push(finding);
      moduleGroups.set(finding.module, existing);
    });

    // Generate recommendations per module
    moduleGroups.forEach((moduleFindings, module) => {
      switch (module) {
        case 'prompt_injection':
          recommendations.push('Review input for potential prompt injection attempts');
          recommendations.push('Consider implementing input sanitization');
          break;
        case 'command_validator':
          recommendations.push('Validate and sanitize any system commands');
          recommendations.push('Use parameterized commands instead of string concatenation');
          break;
        case 'url_validator':
          recommendations.push('Validate and whitelist allowed URL patterns');
          recommendations.push('Implement URL parsing and domain verification');
          break;
        case 'path_validator':
          recommendations.push('Validate file paths against allowed directories');
          recommendations.push('Use path normalization to prevent traversal attacks');
          break;
        case 'secret_detector':
          recommendations.push('Remove any exposed secrets or credentials');
          recommendations.push('Rotate compromised credentials immediately');
          break;
        case 'content_scanner':
          recommendations.push('Review content for policy violations');
          recommendations.push('Implement content filtering or moderation');
          break;
        case 'injection_validator':
          recommendations.push('Sanitize inputs to prevent injection attacks');
          recommendations.push('Use parameterized queries and prepared statements');
          break;
        case 'exfiltration_detector':
          recommendations.push('Review outbound connections for data exfiltration attempts');
          recommendations.push('Implement egress filtering and data loss prevention');
          break;
        case 'code_execution_detector':
          recommendations.push('Review input for code execution attempts');
          recommendations.push('Restrict dynamic code evaluation and sandboxing');
          break;
        case 'serialization_detector':
          recommendations.push('Avoid deserializing untrusted data');
          recommendations.push('Use safe deserialization methods with type allowlists');
          break;
      }
    });

    // Add action-specific recommendations
    if (action === Action.BLOCK || action === Action.BLOCK_NOTIFY) {
      recommendations.push('This request has been blocked due to security concerns');
      recommendations.push('Contact security team if you believe this is a false positive');
    }

    // Deduplicate recommendations
    return Array.from(new Set(recommendations));
  }

  /**
   * Queue database write for async processing
   * @private
   */
  private queueDatabaseWrite(result: ValidationResult, metadata: ValidationMetadata): void {
    try {
      const normalizedText = result.normalizedText || '-';
      const event: SecurityEvent = {
        event_type: 'validation',
        severity: result.severity,
        action_taken: result.action,
        user_id: metadata.userId,
        session_id: metadata.sessionId,
        input_text: normalizedText,
        patterns_matched: JSON.stringify(
          result.findings.map(f => ({
            module: f.module,
            patternId: f.pattern.id,
            severity: f.severity
          }))
        ),
        fingerprint: result.fingerprint,
        module: result.findings.length > 0 ? result.findings[0].module : 'none',
        metadata: JSON.stringify({
          findingCount: result.findings.length,
          modulesConcerned: Array.from(new Set(result.findings.map(f => f.module))),
          context: metadata.context
        })
      };

      this.writeQueue.enqueue(event);
    } catch (error) {
      console.error('Error queuing database write:', error);
    }
  }
}

import { Severity, Finding } from '../types';

/**
 * Result of severity calculation
 */
export interface SeverityResult {
  severity: Severity;
  reasoning: string;
  findingCount: number;
  modulesConcerned: string[];
  severityBreakdown?: Record<Severity, number>;
}

/**
 * SeverityScorer aggregates findings from all detection modules and calculates
 * the final severity level.
 *
 * Strategy: Highest severity wins (most conservative approach)
 *
 * @example
 * ```typescript
 * const scorer = new SeverityScorer();
 * const result = scorer.calculateSeverity(findings);
 * console.log(result.severity); // CRITICAL
 * console.log(result.reasoning); // "Overall severity: CRITICAL (3 findings across 2 modules)"
 * ```
 */
export class SeverityScorer {
  private readonly severityWeight: Record<Severity, number> = {
    [Severity.SAFE]: 0,
    [Severity.LOW]: 1,
    [Severity.MEDIUM]: 2,
    [Severity.HIGH]: 3,
    [Severity.CRITICAL]: 4
  };

  /**
   * Calculate the overall severity from multiple findings
   *
   * @param findings - Array of findings from detection modules
   * @returns SeverityResult with calculated severity and analysis
   * @throws Error if findings is not an array
   */
  calculateSeverity(findings: Finding[]): SeverityResult {
    // Validate input
    if (!Array.isArray(findings)) {
      throw new Error('Findings must be an array');
    }

    // Handle empty findings
    if (findings.length === 0) {
      return {
        severity: Severity.SAFE,
        reasoning: 'No security findings detected. Input appears safe.',
        findingCount: 0,
        modulesConcerned: [],
        severityBreakdown: {
          [Severity.SAFE]: 0,
          [Severity.LOW]: 0,
          [Severity.MEDIUM]: 0,
          [Severity.HIGH]: 0,
          [Severity.CRITICAL]: 0
        }
      };
    }

    // Calculate highest severity (most conservative approach)
    let highestSeverity = Severity.SAFE;
    let highestWeight = 0;

    // Track modules and severity breakdown
    const moduleSet = new Set<string>();
    const severityBreakdown: Record<Severity, number> = {
      [Severity.SAFE]: 0,
      [Severity.LOW]: 0,
      [Severity.MEDIUM]: 0,
      [Severity.HIGH]: 0,
      [Severity.CRITICAL]: 0
    };

    for (const finding of findings) {
      const weight = this.severityWeight[finding.severity];

      // Update severity breakdown
      severityBreakdown[finding.severity]++;

      // Track module
      moduleSet.add(finding.module);

      // Update highest severity
      if (weight > highestWeight) {
        highestWeight = weight;
        highestSeverity = finding.severity;
      }
    }

    const modulesConcerned = Array.from(moduleSet);

    // Build reasoning
    const reasoning = this.buildReasoning(
      highestSeverity,
      findings.length,
      modulesConcerned.length,
      severityBreakdown
    );

    return {
      severity: highestSeverity,
      reasoning,
      findingCount: findings.length,
      modulesConcerned,
      severityBreakdown
    };
  }

  /**
   * Build a human-readable reasoning string
   * @private
   */
  private buildReasoning(
    severity: Severity,
    findingCount: number,
    moduleCount: number,
    breakdown: Record<Severity, number>
  ): string {
    const parts: string[] = [];

    // Main severity statement
    parts.push(`Overall severity: ${severity}`);

    // Finding and module counts
    const findingText = findingCount === 1 ? '1 finding' : `${findingCount} findings`;
    const moduleText = moduleCount === 1 ? '1 module' : `${moduleCount} modules`;
    parts.push(`(${findingText} across ${moduleText})`);

    // Add breakdown for multiple findings
    if (findingCount > 1) {
      const breakdownParts: string[] = [];
      if (breakdown[Severity.CRITICAL] > 0) {
        breakdownParts.push(`${breakdown[Severity.CRITICAL]} CRITICAL`);
      }
      if (breakdown[Severity.HIGH] > 0) {
        breakdownParts.push(`${breakdown[Severity.HIGH]} HIGH`);
      }
      if (breakdown[Severity.MEDIUM] > 0) {
        breakdownParts.push(`${breakdown[Severity.MEDIUM]} MEDIUM`);
      }
      if (breakdown[Severity.LOW] > 0) {
        breakdownParts.push(`${breakdown[Severity.LOW]} LOW`);
      }

      if (breakdownParts.length > 0) {
        parts.push(`- Breakdown: ${breakdownParts.join(', ')}`);
      }
    }

    return parts.join(' ');
  }
}

/**
 * OpenClaw Hook System Types
 *
 * Type definitions for OpenClaw's event-driven hook system.
 */

/**
 * Hook Event - base event structure
 */
export interface HookEvent {
  type: string;
  action: string;
  data?: Record<string, any>;
  user?: {
    id: string;
    email?: string;
    name?: string;
  };
  session?: {
    id: string;
    startTime?: Date;
  };
  api?: {
    registerPlugin?: (name: string, handler: PluginHandler) => void;
    [key: string]: any;
  };
}

/**
 * Command Event - triggered when user executes commands
 */
export interface CommandEvent extends HookEvent {
  type: "command";
  action: "new" | "edit" | "cancel";
  data: {
    input?: string;
    prompt?: string;
    userId?: string;
    sessionId?: string;
    [key: string]: any;
  };
}

/**
 * Agent Event - triggered during agent lifecycle
 */
export interface AgentEvent extends HookEvent {
  type: "agent";
  action: "bootstrap" | "start" | "stop" | "error";
  data?: {
    agentId?: string;
    [key: string]: any;
  };
}

/**
 * Tool Event - triggered during tool execution
 */
export interface ToolEvent extends HookEvent {
  type: "tool";
  action: "call" | "result" | "error";
  data: {
    toolName?: string;
    parameters?: Array<{
      name: string;
      value: any;
      type?: string;
    }>;
    result?: any;
    error?: Error;
    [key: string]: any;
  };
}

/**
 * Plugin Handler - function signature for plugin API handlers
 */
export type PluginHandler = (data: any) => Promise<void> | void;

/**
 * Hook Handler - main function signature for hook handlers
 */
export type HookHandler = (event: HookEvent) => Promise<void> | void;

/**
 * Hook Metadata - from HOOK.md frontmatter
 */
export interface HookMetadata {
  name: string;
  description: string;
  metadata: {
    openclaw: {
      emoji: string;
      events: string[];
      plugin_api?: string;
    };
  };
}

import { describe, it, expect } from '@jest/globals';
import { CodeExecutionDetector } from '../detector';
import { ModuleConfig } from '../../../types';

describe('CodeExecutionDetector', () => {
  const defaultConfig: ModuleConfig = {
    enabled: true
  };

  describe('constructor', () => {
    it('should create an instance with valid config', () => {
      const detector = new CodeExecutionDetector(defaultConfig);
      expect(detector).toBeInstanceOf(CodeExecutionDetector);
    });

    it('should throw error if config is invalid', () => {
      expect(() => new CodeExecutionDetector(null as any)).toThrow();
    });
  });

  describe('scan', () => {
    describe('Node.js patterns', () => {
      it('should detect process.exit()', async () => {
        const detector = new CodeExecutionDetector(defaultConfig);
        const text = 'process.exit(1)';

        const findings = await detector.scan(text);

        expect(findings.length).toBeGreaterThan(0);
        expect(findings.some(f => f.pattern.subcategory === 'nodejs_process_exit')).toBe(true);
      });

